  // O banco nativo é AUTORAL (escrito no estilo das bancas), não prova oficial: o rótulo precisa dizer isso.
  // O campo "board" continua indicando o estilo (usado pelos filtros por banca).
  // As alternativas são embaralhadas de forma determinística (mesma ordem em toda sessão) para a resposta certa
  // não ficar quase sempre em B; questões cujas alternativas dependem da ordem não são tocadas.
  function inferLegalNormaBase(q) {
    const raw = `${q?.topic || ''} ${q?.statement || ''} ${q?.explanation || ''}`;
    const mSumVinc = raw.match(/S[úu]mula\s+Vinculante\s+n?[º°]?\s*\d+/i);
    if (mSumVinc) return `${mSumVinc[0]} do STF`;
    const mSum = raw.match(/S[úu]mula\s+n?[º°]?\s*\d+\s+do\s+(?:STF|STJ)/i);
    if (mSum) return mSum[0];
    const mLei = raw.match(/Lei\s+(?:Complementar\s+)?n?[º°]?\s*[\d.]+\/\d{4}/i);
    const mArt = raw.match(/art(?:igo)?\.?\s*\d+[º°]?(?:-[A-Z])?(?:,\s*(?:inciso\s+)?[IVXLCDM]+|\s*,\s*§\s*\d+[º°]?)?/i);
    if (mLei && mArt) return `${mLei[0]} (${mArt[0]})`;
    if (mLei) return mLei[0];
    if (/Constitui[çc][ãa]o\s+Federal|CF\/88/i.test(raw) && mArt) return `CF/88 (${mArt[0]})`;
    if (/C[óo]digo\s+Penal|\bCP\b/i.test(raw) && mArt) return `Código Penal (${mArt[0]})`;
    if (/C[óo]digo\s+de\s+Processo\s+Penal|\bCPP\b/i.test(raw) && mArt) return `CPP (${mArt[0]})`;
    if (/Declara[çc][ãa]o\s+Universal\s+dos\s+Direitos\s+Humanos|DUDH/i.test(raw)) return 'DUDH (ONU/1948)';
    const subj = String(q?.subject || '');
    if (/Portugu[êe]s/i.test(subj)) return 'Gramática Normativa / Interpretação Textual';
    if (/Racioc[íi]nio|Matem[áa]tica/i.test(subj)) return 'Lógica Proposicional e Quantitativa';
    if (/Inform[áa]tica/i.test(subj)) return 'Segurança da Informação (CERT.br) e Redes TCP/IP';
    if (/Hist[óo]ria/i.test(subj)) return 'Historiografia Oficial de Pernambuco';
    return 'Bibliografia Oficial de Concursos Policiais';
  }
  function normalizeNativeQuestionBank(list) {
    const orderDependent = /\b(todas|nenhuma|ambas|anterior(?:es)?|acima|abaixo)\b|\balternativas?\s+[a-e]\b|\b[a-e]\s+e\s+[a-e]\b/i;
    const numeralOnly = /^\s*(?:[IVX]+|\d+)(?:\s*(?:,|e|ou)\s*(?:[IVX]+|\d+))*\s*(?:apenas|somente)?\.?\s*$/i;
    const letters = 'ABCDE';
    for (const q of list) {
      q.origin = 'autoral';
      q.norma_base = q.norma_base || inferLegalNormaBase(q);
      q.content_version = q.content_version || '2026-11';
      const opts = q.options;
      if (!Array.isArray(opts) || opts.length < 3 || opts.length > 5 || !Number.isInteger(q.correct_index)) continue;
      if (opts.some(o => orderDependent.test(String(o))) || opts.every(o => numeralOnly.test(String(o).trim()))) continue;
      const expl = String(q.explanation || '');
      // Bare grouped references ("B, C e D") may refer to assertions rather than option labels.
      // Preserve their order instead of guessing how to rewrite the commentary.
      if (/\b[A-E](?:\s*,\s*[A-E])*(?:\s+(?:e|ou)\s+[A-E])\b/.test(expl)) continue;
      const stripped = expl.replace(/Alternativa correta:\s*[A-E]\)[^|]*/g, '').replace(/An[aá]lise das alternativas:[^|]*/g, '');
      if (/\b[A-E]\)/.test(stripped) || /\b(?:alternativa|letra)\s+[A-E]\b/i.test(stripped)) continue;
      let h = 2166136261;
      for (const ch of String(q.statement)) h = Math.imul(h ^ ch.charCodeAt(0), 16777619) >>> 0;
      const rand = () => { h = (h + 0x6D2B79F5) >>> 0; let x = Math.imul(h ^ (h >>> 15), 1 | h); x ^= x + Math.imul(x ^ (x >>> 7), 61 | x); return ((x ^ (x >>> 14)) >>> 0) / 4294967296; };
      const order = opts.map((_, i) => i);
      for (let i = order.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
      const newPos = order.map((_, oldIdx) => order.indexOf(oldIdx));
      q.options = order.map(i => opts[i]);
      q.correct_index = newPos[q.correct_index];
      const remap = letter => letters[newPos[letters.indexOf(letter)]];
      let next = expl.replace(/(Alternativa correta:\s*)([A-E])\)/, (_, lead, l) => `${lead}${remap(l)})`);
      next = next.replace(/(An[aá]lise das alternativas:\s*)([^|]*)/, (_, lead, body) => {
        const items = body.trim().split(/;\s*(?=[A-E]\)\s)/).map(item => item.replace(/\b([A-E])\)/g, (__, l) => `${remap(l)})`));
        items.sort((a, b) => a.charAt(0).localeCompare(b.charAt(0)));
        return `${lead}${items.join('; ')} `;
      });
      q.explanation = next;
    }
    return list;
  }
  normalizeNativeQuestionBank(NATIVE_POLICE_QUESTION_BANK);
  window.NATIVE_POLICE_QUESTION_BANK = NATIVE_POLICE_QUESTION_BANK;

  // Carregamento sob demanda de banco externo JSON (permite corrigir ou atualizar questões sem novo deploy de JS)
  async function syncExternalNativeQuestionBank() {
    if (typeof fetch !== 'function') return;
    try {
      const res = await fetch('./native-question-bank.json', { cache: 'no-cache' });
      if (!res.ok) return;
      const extList = await res.json();
      if (Array.isArray(extList) && extList.length >= NATIVE_POLICE_QUESTION_BANK.length) {
        NATIVE_POLICE_QUESTION_BANK.length = 0;
        extList.forEach(item => NATIVE_POLICE_QUESTION_BANK.push(item));
      }
    } catch (_e) {}
  }
  if (typeof window !== 'undefined') setTimeout(syncExternalNativeQuestionBank, 1200);

  function questionMatchesBoardFilter(item, boardFilter) {
    if (!boardFilter || boardFilter === 'all') return true;
    const target = String(boardFilter).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').trim();
    // Explanations often compare boards; that does not make the question belong to each one.
    const declaredBoard=String(item?.board||'').trim();
    const hay = (declaredBoard&&!/^(?:prova oficial|banca n[aã]o informada|desconhecida)$/i.test(declaredBoard)?declaredBoard:String(item?.statement||'').slice(0,180)).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');
    if (target.includes('aocp')) return /aocp/.test(hay);
    if (target.includes('cebraspe') || target.includes('cespe')) return /cebraspe|cespe/.test(hay);
    if (target.includes('fgv')) return /\bfgv\b|fundacao getulio vargas/.test(hay);
    if (target.includes('upenet') || target.includes('iaupe')) return /upenet|iaupe/.test(hay);
    if (target.includes('ibfc')) return /\bibfc\b/.test(hay);
    if (target.includes('idecan')) return /idecan/.test(hay);
    return hay.includes(target);
  }

  function subjectIconForName(subj) {
    const k = String(subj || '').toLocaleLowerCase('pt-BR');
    if (/portugues|redacao|gramatica/.test(k)) return '📘';
    if (/constitucional/.test(k)) return '⚖️';
    if (/extravagante|especial|drogas|maria|tortura|abuso/.test(k)) return '🚨';
    if (/processual\s+penal|processo\s+penal/.test(k)) return '🔎';
    if (/penal/.test(k)) return '🚔';
    if (/administrativo/.test(k)) return '🏛️';
    if (/raciocinio|logico|rlm|matematica/.test(k)) return '🧠';
    if (/informatica|computa/.test(k)) return '💻';
    if (/historia|geografia|pernambuco/.test(k)) return '🏺';
    if (/humanos|dudh/.test(k)) return '🕊️';
    if (/militar|estatuto/.test(k)) return '🎖️';
    if (/fisica|incendio/.test(k)) return '🔥';
    if (/biologia|socorro|anatomia/.test(k)) return '🧬';
    return '🎯';
  }
  window.subjectIconForName = subjectIconForName;

  function highlightCommandsAndLaws(rawSegment, itemObj) {
    let safe = escText(String(rawSegment || '').trim());
    safe = safe.replace(/\b(INCORRETA|INCORRETO|CORRETA|CORRETO|EXCETO|SALVO|NÃO|ERRADA|ERRADO)\b/g, '<span class="qCmdHighlight">$1</span>');
    safe = safe.replace(/\b((?:Art(?:igo)?\.?\s*\d+[º°ª]?(?:-[A-Z])?(?:,\s*§\s*\d+[º°]?)?(?:,\s*inciso\s+[IVXLCDM]+)?)|(?:Lei\s+(?:Complementar\s+|Federal\s+|Estadual\s+)?n?[º°.]?\s*[\d.]+(?:\/\d{2,4})?)|(?:S[úu]mula(?:\s+Vinculante)?\s+n?[º°.]?\s*\d+)|(?:CF\/88|Constitui[cç][aã]o\s+Federal))\b/gi, '<span class="lawCiteBadge">⚖️ $1</span>');
    if (/\b(express[aã]o em destaque|termo em destaque|termo destacado|locu[cç][aã]o em destaque|conjun[cç][aã]o em destaque|voc[áa]bulo em destaque|elemento destacado|segmento destacado)\b/i.test(safe) && !/<mark\b/i.test(safe)) {
      safe = safe.replace(/\b([ÀA]\s+medida\s+que|Na\s+medida\s+em\s+que|[ÀA]\s+propor[cç][aã]o\s+que|Ao\s+passo\s+que|Conquanto|Porquanto|Contanto\s+que|Posto\s+que|Ainda\s+que|Mesmo\s+que|Visto\s+que|J[áa]\s+que|Uma\s+vez\s+que|Desde\s+que|A\s+menos\s+que|Sem\s+que|Para\s+que|A\s+fim\s+de\s+que|De\s+modo\s+que|Todavia|Entretanto|No\s+entanto|Portanto|Por\s+conseguinte|Dessarte|Outrossim|Destarte)\b/i, '<mark class="targetExprHighlight">$1</mark>');
    }
    return safe;
  }

  function splitQuestionAssociatedText(rawText, itemObj) {
    const full = String(rawText || '').trim();
    const explicit = String(itemObj?.associated_text || '').trim();
    let assoc = '';
    let stem = full;

    // 1. Padrão com quebra dupla (Texto-base: ... \n\n Enunciado)
    const tbMatch = full.match(/^Texto-base:\s*([\s\S]+?)\n\n+([\s\S]+)$/i)
      || full.match(/^Texto\s+(?:associado|de\s+apoio):\s*([\s\S]+?)\n\n+([\s\S]+)$/i);
    if (tbMatch) {
      assoc = tbMatch[1].trim();
      stem = tbMatch[2].trim();
    } else if (/^Texto-base:\s*/i.test(full)) {
      // 2. Caso o \n\n tenha sido achatado em espaço simples em bancos antigos
      const bodyNoPrefix = full.replace(/^Texto-base:\s*/i, '').trim();
      const cmdMatch = bodyNoPrefix.match(/^([\s\S]{45,}?)\s+((?:\([A-Za-zÀ-ÿ0-9\s—\-/]+\)\s*)?(?:\[Julgue\s+o\s+item[^\]]*\]\s*|QUEST[AÃ]O\s*\d+[\s.:–-]*|Assinale\s+a\s+(?:alternativa|op[cç][aã]o)|Marque\s+a\s+(?:alternativa|op[cç][aã]o)|Julgue\s+o\s+item|De\s+acordo\s+com\s+(?:o\s+texto|a\s+leitura|o\s+autor)|Segundo\s+o\s+(?:texto|autor)|Conforme\s+o\s+(?:texto|autor)|Com\s+base\s+n[ao]\s+(?:texto|leitura)|A\s+respeito\s+d[eo]\s+texto|No\s+\d+[º°ª]?\s*par[áa]grafo|Infere-se\s+d[eo]\s+texto|Depreende-se\s+d[eo]\s+texto|A\s+estrutura\s+argumentativa)[\s\S]+)$/i);
      if (cmdMatch) {
        assoc = cmdMatch[1].trim();
        stem = cmdMatch[2].trim();
      }
    } else if (explicit && full.startsWith(explicit)) {
      assoc = explicit;
      stem = full.slice(explicit.length).replace(/^[:\s\-–]+/, '').trim() || full;
    } else if (explicit && !full.includes(explicit.slice(0, 40))) {
      assoc = explicit;
      stem = full;
    } else {
      // 3. Questão que já começa com TEXTO I / Leia o texto sem prefixo Texto-base:
      const autoSplit = full.match(/^((?:TEXTO\s+(?:[IVX]+|\d+)\b|Leia\s+(?:atentamente\s+)?(?:o|os|a|as)\s+(?:texto|trecho|poema|cr[ôo]nica|fragmento))[\s\S]{90,}?)(?:\n\n+|\s{2,}|(?=(?:\([A-Za-zÀ-ÿ0-9\s—\-/]+\)\s*)?(?:Assinale\s+a|Marque\s+a|De\s+acordo\s+com|Segundo\s+o|Com\s+base\s+no|No\s+\d+[º°]\s*par[áa]grafo)))((?:\([A-Za-zÀ-ÿ0-9\s—\-/]+\)\s*)?(?:No\s+\d+[º°]|De\s+acordo\s+com|Segundo\s+o|Conforme\s+o|Assinale\s+a|Marque\s+a|Julgue\s+o|Com\s+base\s+no|A\s+respeito\s+do|Infere-se|Depreende-se|A\s+estrutura|Na\s+linha|No\s+trecho)[\s\S]+)$/i);
      if (autoSplit) {
        assoc = autoSplit[1].trim();
        stem = autoSplit[2].trim();
      }
    }

    // 4. Fallback inteligente: se a questão cita "De acordo com o texto / No 2º parágrafo" mas o texto ficou no resumo vinculado
    if ((!assoc || assoc.length < 35) && itemObj && /\b(segundo o texto|de acordo com o texto|conforme o texto|no \d+[º°ª]?\s*par[áa]grafo|infere-se do texto|depreende-se do texto|leia o texto)\b/i.test(full)) {
      const rel = typeof findRelatedSummary === 'function' ? findRelatedSummary(itemObj) : null;
      const fallbackText = String(rel?.example || rel?.explanation || '').trim();
      if (fallbackText.length >= 60) {
        assoc = fallbackText;
      }
    }

    if (!assoc || assoc.length < 35) {
      return { associatedText: '', questionStem: full, paragraphs: [], readingTimeMin: 1 };
    }
    const rawParas = assoc.includes('\n\n')
      ? assoc.split(/\n{2,}|(?=\bTEXTO\s+(?:[IVX]+|\d+)\b)/)
      : assoc.split(/(?<=\.)\s+(?=[A-ZÁÉÍÓÚÂÊÔÃÕÇ“"])/);
    const paragraphs = rawParas.map(p => p.replace(/\s+/g, ' ').trim()).filter(Boolean);
    const words = assoc.split(/\s+/).filter(Boolean).length;
    const readingTimeMin = Math.max(1, Math.ceil(words / 180));
    return { associatedText: assoc, questionStem: stem, paragraphs, readingTimeMin };
  }
  window.splitQuestionAssociatedText = splitQuestionAssociatedText;

  window.granKeepTextOpen = false;
  window.granTextFontScale = 100;

  window.toggleGranAssociatedText = function(btn) {
    const wrapper = btn?.closest('[data-assoc-wrapper]');
    if (!wrapper) return;
    const body = wrapper.querySelector('.granAssocBody');
    const badge = wrapper.querySelector('.granAssocPlusBadge');
    const linkTxt = wrapper.querySelector('.granAssocLinkText');
    if (!body) return;
    const willOpen = body.hasAttribute('hidden');
    if (willOpen) {
      body.removeAttribute('hidden');
      wrapper.classList.add('open');
      btn.setAttribute('aria-expanded', 'true');
      if (badge) badge.textContent = '▴';
      if (linkTxt) linkTxt.textContent = 'Ocultar texto de apoio da questão';
    } else {
      body.setAttribute('hidden', '');
      wrapper.classList.remove('open');
      btn.setAttribute('aria-expanded', 'false');
      if (badge) badge.textContent = '▾';
      if (linkTxt) linkTxt.textContent = 'Ler texto de apoio da questão';
    }
  };

  window.toggleGranPinText = function(btn) {
    window.granKeepTextOpen = !window.granKeepTextOpen;
    if (btn) {
      btn.classList.toggle('pinned', window.granKeepTextOpen);
      btn.textContent = window.granKeepTextOpen ? '📌 Texto fixado' : '📌 Fixar aberto';
    }
    if (window.granKeepTextOpen) {
      const wrapper = btn?.closest('[data-assoc-wrapper]');
      const body = wrapper?.querySelector('.granAssocBody');
      if (body && body.hasAttribute('hidden')) {
        window.toggleGranAssociatedText(wrapper.querySelector('.granAssocToggleBtn'));
      }
    }
    if (typeof toast === 'function') {
      toast(window.granKeepTextOpen ? 'Texto de apoio ficará aberto nas próximas questões.' : 'Texto de apoio voltará a abrir recolhido.');
    }
  };

  window.adjustGranTextFont = function(btn, delta) {
    window.granTextFontScale = Math.max(85, Math.min(130, (window.granTextFontScale || 100) + delta * 8));
    const wrapper = btn?.closest('[data-assoc-wrapper]');
    const content = wrapper?.querySelector('.granAssocContent');
    if (content) content.style.fontSize = `${window.granTextFontScale}%`;
  };

  function formatStatementWithHighlights(rawText, itemObj) {
    const parsed = splitQuestionAssociatedText(rawText, itemObj);
    const hasMissingFigureRef = !parsed.associatedText && /\b(observe a tirinha|analise a charge|observe a charge|na tirinha a seguir|no quadrinho acima|observe a figura abaixo|de acordo com o gr[áa]fico a seguir)\b/i.test(parsed.questionStem);
    const figureWarningHtml = hasMissingFigureRef
      ? `<div class="visualFigureAlert"><span>🖼️ <b>Atenção:</b> Esta questão faz referência a uma imagem/tirinha/gráfico do PDF original.</span><button type="button" class="ghost small" onclick="if(typeof window.skipQuestionBlank==='function')window.skipQuestionBlank()" style="width:auto;padding:4px 10px;font-size:.74rem">⚪ Deixar em Branco (0 pt)</button></div>`
      : '';

    if (!parsed.associatedText) {
      return figureWarningHtml + highlightCommandsAndLaws(parsed.questionStem);
    }

    const isOpen = Boolean(window.granKeepTextOpen);
    const paraHtml = parsed.paragraphs.map((p, idx) => {
      const isHeader = /^(?:TEXTO\s+(?:[IVX]+|\d+)|Leia\s+o\s+texto)/i.test(p) && p.length < 95;
      if (isHeader) {
        return `<div class="granAssocParagraph" style="font-weight:800;color:#63e7ff;margin-bottom:8px">${escText(p)}</div>`;
      }
      return `<p class="granAssocParagraph"><span class="granAssocParaBadge">§ ${idx + 1}º</span>${highlightCommandsAndLaws(p)}</p>`;
    }).join('');

    return `
      <div class="granAssocWrapper ${isOpen ? 'open' : ''}" data-assoc-wrapper>
        <div class="granAssocHeader">
          <button type="button" class="granAssocToggleBtn" onclick="window.toggleGranAssociatedText(this)" aria-expanded="${isOpen ? 'true' : 'false'}" title="Ler texto referente à questão">
            <span class="granAssocPlusBadge">${isOpen ? '▴' : '▾'}</span>
            <span>📖 <span class="granAssocLinkText">${isOpen ? 'Ocultar texto de apoio da questão' : 'Ler texto de apoio da questão'}</span></span>
            <span class="granAssocMeta">${parsed.paragraphs.length} parágrafo(s) · ~${parsed.readingTimeMin} min</span>
          </button>
          <button type="button" class="granAssocPinBtn ${isOpen ? 'pinned' : ''}" onclick="window.toggleGranPinText(this)" title="Manter o texto de apoio aberto automaticamente nas próximas questões">${isOpen ? '📌 Texto fixado' : '📌 Fixar aberto'}</button>
        </div>
        <div class="granAssocBody" ${isOpen ? '' : 'hidden'}>
          <div class="granAssocToolbar">
            <span>📄 Texto da Questão (Parágrafos numerados)</span>
            <div style="display:flex;gap:6px">
              <button type="button" class="ghost small" onclick="window.adjustGranTextFont(this,-1)" style="width:auto;min-height:26px;padding:2px 8px;font-size:.72rem">A-</button>
              <button type="button" class="ghost small" onclick="window.adjustGranTextFont(this,1)" style="width:auto;min-height:26px;padding:2px 8px;font-size:.72rem">A+</button>
            </div>
          </div>
          <div class="granAssocContent" style="font-size:${window.granTextFontScale || 100}%">${paraHtml}</div>
        </div>
      </div>
      <div class="qCmdStemBlock">
        <div class="qCmdStemLabel">🎯 Comando da Questão</div>
        <div>${highlightCommandsAndLaws(parsed.questionStem)}</div>
      </div>
    `.trim();
  }
  window.formatStatementWithHighlights = formatStatementWithHighlights;
  window.questionMatchesBoardFilter = questionMatchesBoardFilter;

  // Track source objects per destination array: repeated filters must not rehash the bank.
  const nativeBankLoadedSources = new WeakMap();
  function ensureNativeQuestionBankLoaded() {
    if (typeof ALL_QUESTIONS === 'undefined' || !Array.isArray(ALL_QUESTIONS)) return;
    let loaded = nativeBankLoadedSources.get(ALL_QUESTIONS);
    if (!loaded) { loaded = new WeakSet(); nativeBankLoadedSources.set(ALL_QUESTIONS, loaded); }
    const pending = NATIVE_POLICE_QUESTION_BANK.filter(item => !loaded.has(item));
    if (!pending.length) return;
    const existingFp = new Set(ALL_QUESTIONS.map(qItem => questionFingerprint(qItem)));
    let added = 0;
    for (const item of pending) {
      loaded.add(item);
      const normalized = {
        ...item,
        subject: canonicalSubjectName(item.subject),
        is_native_bank: true
      };
      const fp = questionFingerprint(normalized);
      if (!existingFp.has(fp)) {
        existingFp.add(fp);
        ALL_QUESTIONS.push(normalized);
        added++;
      }
    }
    if (added > 0 && typeof window.updateLocalDbBadgeUI === 'function') {
      window.updateLocalDbBadgeUI();
    }
  }
  window.ensureNativeQuestionBankLoaded = ensureNativeQuestionBankLoaded;

  // ── r145: Acoplamento Pedagógico Fiel ao Edital + Horas Líquidas Compactas + Ciclo Tático Sincronizado com a Missão ──
  // Platform help is a separate catalogue, never study data or AI context.
  function isPlatformManualStudyArtifact(value){
    if(typeof window.isHunterManualArtifact==='function')return window.isHunterManualArtifact(value);
    if(typeof window.JornadaManuals?.isManual==='function')return window.JornadaManuals.isManual(value);
    const fields=Array.isArray(value)?[value[0],value[1],value[3],value[4]]:
      value&&typeof value==='object'?[value.id,value.category,value.subject,value.title,value.source,value.content_kind]:[value];
    return fields.some(field=>{
      const text=String(field||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
      return /^manual-(?:01-ciclo-estudos|02-dominando-questoes|03-revisao-pos-edital|04-guia-passo-a-passo)$/.test(text)||
        /\b(?:manuais|manual(?: oficial)?) do cacador\b/.test(text)||text==='platform_manual';
    });
  }
  function purgeHunterManualStudyArtifacts(){
    let removed=0;
    const purge=list=>{
      if(!Array.isArray(list))return;
      for(let i=list.length-1;i>=0;i--)if(isPlatformManualStudyArtifact(list[i])){list.splice(i,1);removed++;}
    };
    purge(window.BASIC_SUMMARIES);
    purge(window.MATERIAL_DEEP_DIVES);
    if(typeof ALL_SUMMARIES!=='undefined')purge(ALL_SUMMARIES);
    if(typeof ALL_FLASHCARDS!=='undefined')purge(ALL_FLASHCARDS);
    if(typeof ALL_QUESTIONS!=='undefined')purge(ALL_QUESTIONS);
    if(typeof LEARNING_SUBJECTS!=='undefined')purge(LEARNING_SUBJECTS);
    // Remove only obsolete filter choices, without changing study progress.
    if(typeof libraryUI!=='undefined'&&libraryUI){
      for(const field of ['summaryFilter','cardFilter','trailSubject']){
        for(const [portal,value] of Object.entries(libraryUI[field]||{}))if(isPlatformManualStudyArtifact(value)){
          if(field==='trailSubject')delete libraryUI[field][portal];else libraryUI[field][portal]='all';
        }
      }
    }
    if(typeof document!=='undefined'){
      document.querySelector('#openManuaisCacadorBtn')?.remove();
      for(const selector of ['#summaryFilter','#cardFilter','#questionSubject','#noteSubject']){
        const select=document.querySelector(selector);
        if(!select?.options)continue;
        const reset=isPlatformManualStudyArtifact(select.value);
        for(const option of [...select.options])if(isPlatformManualStudyArtifact(option.value)||isPlatformManualStudyArtifact(option.textContent))option.remove();
        if(reset)select.value=[...select.options].some(option=>option.value==='all')?'all':select.options[0]?.value||'';
      }
    }
    return removed;
  }
  window.purgeHunterManualStudyArtifacts=purgeHunterManualStudyArtifacts;

  function getActiveEditalSubjectsList(){
    try{
      const missions=typeof missionPool==='function'?missionPool().filter(m=>m&&m.subject&&!isPlatformManualStudyArtifact(m)&&!String(m.id||'').startsWith('setup-')):[];
      const seen=new Set();
      const list=[];
      for(const m of missions){
        const c=canonicalSubjectName(m.subject);
        const k=subjectKey(c);
        if(c&&k&&!seen.has(k)){
          seen.add(k);
          list.push(c);
        }
      }
      if(list.length)return list;
    }catch(_e){}
    const campName=String((typeof activeCampaign==='function'?activeCampaign()?.name:'')||'').toLowerCase();
    const isBombeiro=/cbm|bombeiro/.test(campName);
    const base=['Língua Portuguesa','História de Pernambuco','Raciocínio Lógico-Matemático','Informática','Direito Constitucional','Direitos Humanos','Legislação Extravagante','Direito Militar'];
    return isBombeiro?[...base,'Física','Biologia']:base;
  }

  function ensureNativePedagogicalCouplingLoaded(){
    try{
      purgeHunterManualStudyArtifacts();
      const allowedSubjects=getActiveEditalSubjectsList();
      const allowedKeys=new Set(allowedSubjects.map(s=>subjectKey(s)));
      const campName=String((typeof activeCampaign==='function'?activeCampaign()?.name:'')||'').toLowerCase();
      const isBombeiro=/cbm|bombeiro/.test(campName);

      // Remove Biologia/Física que tenham entrado por engano em portais que não têm essas matérias no edital
      if(!isBombeiro&&typeof ALL_SUMMARIES!=='undefined'&&Array.isArray(ALL_SUMMARIES)){
        for(let i=ALL_SUMMARIES.length-1;i>=0;i--){
          const catKey=subjectKey(ALL_SUMMARIES[i]?.category||'');
          if(ALL_SUMMARIES[i]?.is_native_coupling&&(catKey==='fisica'||catKey==='biologia')&&!allowedKeys.has(catKey)){
            ALL_SUMMARIES.splice(i,1);
          }
        }
      }

      const baseList=[
        ...(typeof window.BASIC_SUMMARIES!=='undefined'&&Array.isArray(window.BASIC_SUMMARIES)?window.BASIC_SUMMARIES:[]),
        ...(typeof window.MATERIAL_DEEP_DIVES!=='undefined'&&Array.isArray(window.MATERIAL_DEEP_DIVES)?window.MATERIAL_DEEP_DIVES:[])
      ].filter(item=>!isPlatformManualStudyArtifact(item));
      if(typeof ALL_SUMMARIES!=='undefined'&&Array.isArray(ALL_SUMMARIES)&&baseList.length){
        const existingIds=new Set(ALL_SUMMARIES.map(s=>String(s?.id||s?.title||'').toLowerCase()));
        for(const item of baseList){
          const rawCat=item.category||item.subject||'Conteúdo Geral';
          const normCat=canonicalSubjectName(rawCat);
          const catKey=subjectKey(normCat);
          // Study material must belong to the active edital; manuals are separate help.
          if(allowedKeys.size&&!allowedKeys.has(catKey))continue;
          const key=String(item?.id||item?.title||'').toLowerCase();
          if(key&&!existingIds.has(key)){
            existingIds.add(key);
            ALL_SUMMARIES.push({
              ...item,
              category:normCat,
              is_native_coupling:true
            });
          }
        }
      }
      if(typeof ALL_FLASHCARDS!=='undefined'&&Array.isArray(window.ALL_FLASHCARDS)&&baseList.length){
        const existingFronts=new Set(ALL_FLASHCARDS.map(c=>String(Array.isArray(c)?c[1]:c?.front||'').toLowerCase()));
        for(const item of baseList){
          const rawCat=item.category||item.subject||'Conteúdo Geral';
          if(isPlatformManualStudyArtifact(item))continue;
          const subj=canonicalSubjectName(rawCat);
          if(allowedKeys.size&&!allowedKeys.has(subjectKey(subj)))continue;
          const front=`[${item.title}] Qual o bizu e a regra central cobrada pelas bancas?`;
          const back=[item.bizu?`💡 Bizu: ${item.bizu}`:'',item.mnemonic?`🧠 Mnemônico: ${item.mnemonic}`:'',item.trap?`⚠️ Pegadinha: ${item.trap}`:'',item.points?.[0]||''].filter(Boolean).join(' | ');
          if(back&&!existingFronts.has(front.toLowerCase())){
            existingFronts.add(front.toLowerCase());
            ALL_FLASHCARDS.push([subj,front,back,item.title,item.source||'Apostila Base & Lei Seca']);
          }
        }
      }
    }catch(_e){}
  }
  window.ensureNativePedagogicalCouplingLoaded=ensureNativePedagogicalCouplingLoaded;

  const ESTUDEI_CYCLE_BLOCKS=[
    {subject:'Língua Portuguesa',minutes:60,mode:'Teoria + Questões'},
    {subject:'História de Pernambuco',minutes:50,mode:'Resumo + Questões'},
    {subject:'Raciocínio Lógico-Matemático',minutes:50,mode:'Prática de Questões'},
    {subject:'Direito Constitucional',minutes:60,mode:'Lei Seca + Questões'},
    {subject:'Informática',minutes:45,mode:'Teoria + Questões'},
    {subject:'Direitos Humanos',minutes:50,mode:'Lei Seca + Questões'},
    {subject:'Legislação Extravagante',minutes:60,mode:'Lei Seca + Flashcards'},
    {subject:'Direito Militar',minutes:50,mode:'Lei Seca + Questões'}
  ];

  function getEstudeiCycleState(){
    const today=typeof localDayKey==='function'?localDayKey():new Date().toISOString().slice(0,10);
    let st={currentIndex:0,completedBlocks:0,activeCategory:'teoria',date:today,categoryMinutes:{teoria:0,lei_seca:0,questoes:0,revisao:0},customSubject:''};
    try{
      const raw=localStorage.getItem('jc_estudei_cycle_v1');
      if(raw)st={...st,...JSON.parse(raw)};
    }catch(_e){}
    if(st.date!==today){
      st.date=today;
      st.categoryMinutes={teoria:0,lei_seca:0,questoes:0,revisao:0};
    }
    st.categoryMinutes=st.categoryMinutes||{teoria:0,lei_seca:0,questoes:0,revisao:0};
    const realTodayMins=Math.max(0,Math.floor(Number(state?.studyByDay?.[today]||0)/60));
    const activeCat=st.activeCategory||'teoria';
    const catKeys=['teoria','lei_seca','questoes','revisao'];
    const totalCatMins=catKeys.reduce((sum,k)=>sum+Math.max(0,Number(st.categoryMinutes[k]||0)),0);
    if(totalCatMins!==realTodayMins){
      const otherMins=catKeys.filter(k=>k!==activeCat).reduce((sum,k)=>sum+Math.max(0,Number(st.categoryMinutes[k]||0)),0);
      if(otherMins<=realTodayMins){
        st.categoryMinutes[activeCat]=realTodayMins-otherMins;
      }else{
        st.categoryMinutes={teoria:0,lei_seca:0,questoes:0,revisao:0};
        st.categoryMinutes[activeCat]=realTodayMins;
      }
      saveEstudeiCycleState(st);
    }
    return st;
  }
  function saveEstudeiCycleState(st){
    try{localStorage.setItem('jc_estudei_cycle_v1',JSON.stringify(st));}catch(_e){}
  }

  function renderEstudeiCycleWidget(){
    ensureNativePedagogicalCouplingLoaded();
    if(typeof document==='undefined')return;

    const st=getEstudeiCycleState();
    const editalSubjects=getActiveEditalSubjectsList();
    const missions=typeof orderedMissions==='function'?orderedMissions():(typeof missionPool==='function'?missionPool():[]);
    const currentDailyMission=missions.find(m=>m.id===state?.daily)||missions.find(m=>!state?.done?.[m.id])||missions[0]||null;
    const missionSubject=currentDailyMission?canonicalSubjectName(currentDailyMission.subject):(editalSubjects[0]||'Língua Portuguesa');

    // Sincronia total: a Matéria em Foco do Ciclo Tático e do Cronômetro é SEMPRE a mesma da Missão Atual!
    let activeIdx=editalSubjects.findIndex(s=>subjectKey(s)===subjectKey(missionSubject));
    if(activeIdx<0)activeIdx=0;
    const currSubject=editalSubjects[activeIdx]||missionSubject;
    if(st.customSubject!==currSubject){st.customSubject=currSubject;saveEstudeiCycleState(st);}
    const nextSubject=editalSubjects[(activeIdx+1)%editalSubjects.length]||currSubject;
    const currTopicObj=currentDailyMission||missions.find(m=>subjectKey(canonicalSubjectName(m.subject))===subjectKey(currSubject)&&!state?.done?.[m.id]);
    const currTopicName=currTopicObj?.name||'Tópico prioritário do edital';

    function switchDailyMissionToSubject(targetSubject){
      const pool=typeof orderedMissions==='function'?orderedMissions():(typeof missionPool==='function'?missionPool():[]);
      if(!pool.length||typeof state!=='object'||!state)return false;
      const targetM=pool.find(m=>subjectKey(canonicalSubjectName(m.subject))===subjectKey(targetSubject)&&!state.done?.[m.id])
        ||pool.find(m=>subjectKey(canonicalSubjectName(m.subject))===subjectKey(targetSubject));
      if(!targetM)return false;
      const today=typeof localDayKey==='function'?localDayKey():new Date().toISOString().slice(0,10);
      const campaignId=state.activeCampaignId;
      state.daily=targetM.id;
      state.dailyDate=today;
      state.dailySteps={};
      state.dailyHistory=Array.isArray(state.dailyHistory)?state.dailyHistory:[];
      const existingPending=state.dailyHistory.find(x=>(!x.campaignId||x.campaignId===campaignId)&&x.date===today&&!x.completedAt);
      if(existingPending){
        existingPending.missionId=targetM.id;
        existingPending.name=targetM.name;
        existingPending.subject=targetM.subject;
        existingPending.selectedAt=new Date().toISOString();
        existingPending.replacedAt=null;
        state.currentDailyHistoryId=existingPending.id;
      }else{
        const entry={id:`daily-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,campaignId,date:today,missionId:targetM.id,name:targetM.name,subject:targetM.subject,selectedAt:new Date().toISOString(),completedAt:null};
        state.dailyHistory.push(entry);
        state.currentDailyHistoryId=entry.id;
      }
      if(typeof save==='function')save();
      if(typeof renderDaily==='function')renderDaily();
      if(typeof renderStreak==='function')renderStreak();
      return true;
    }

    // 1) No Cronômetro de Foco (.card.timer): coloca APENAS a barra compacta de Modalidade de Horas Líquidas (sem aumentar a altura nem criar buraco na coluna esquerda!)
    const timerHost=document.querySelector('.card.timer')||document.querySelector('#clock')?.closest('.card');
    if(timerHost){
      const oldTimerBox=timerHost.querySelector('#estudeiCycleWidget');
      if(oldTimerBox)oldTimerBox.remove();
      const oldCompact=timerHost.querySelector('#timerLiquidCategoryBar');
      if(oldCompact)oldCompact.remove();
      const compactBar=document.createElement('div');
      compactBar.id='timerLiquidCategoryBar';
      compactBar.style.cssText='margin:8px 0 6px;padding:7px 8px;border-radius:10px;background:rgba(7,19,32,0.85);border:1px solid rgba(56,189,248,0.22);text-align:left;';
      compactBar.innerHTML=`
        <div style="font-size:10.5px;color:#94a3b8;margin-bottom:5px;display:flex;justify-content:space-between;align-items:center;">
          <span>⏱️ <b>Modalidade do Cronômetro:</b></span>
          <span style="color:#38bdf8;font-weight:700;">${escText(shortLabel(currSubject,22))}</span>
        </div>
        <div style="display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px;">
          <button type="button" data-estudei-cat="teoria" class="ghost small" style="min-height:28px;padding:3px 2px;font-size:10px;justify-content:center;${st.activeCategory==='teoria'?'border-color:#38bdf8;color:#38bdf8;font-weight:800;background:rgba(56,189,248,0.14);':''}">📖 Teoria<br>${st.categoryMinutes?.teoria||0}m</button>
          <button type="button" data-estudei-cat="lei_seca" class="ghost small" style="min-height:28px;padding:3px 2px;font-size:10px;justify-content:center;${st.activeCategory==='lei_seca'?'border-color:#38bdf8;color:#38bdf8;font-weight:800;background:rgba(56,189,248,0.14);':''}">📜 Lei<br>${st.categoryMinutes?.lei_seca||0}m</button>
          <button type="button" data-estudei-cat="questoes" class="ghost small" style="min-height:28px;padding:3px 2px;font-size:10px;justify-content:center;${st.activeCategory==='questoes'?'border-color:#38bdf8;color:#38bdf8;font-weight:800;background:rgba(56,189,248,0.14);':''}">🎯 Quest.<br>${st.categoryMinutes?.questoes||0}m</button>
          <button type="button" data-estudei-cat="revisao" class="ghost small" style="min-height:28px;padding:3px 2px;font-size:10px;justify-content:center;${st.activeCategory==='revisao'?'border-color:#38bdf8;color:#38bdf8;font-weight:800;background:rgba(56,189,248,0.14);':''}">🔁 Rev.<br>${st.categoryMinutes?.revisao||0}m</button>
        </div>
      `;
      const manualBtn=timerHost.querySelector('#openManualStudy');
      if(manualBtn)manualBtn.insertAdjacentElement('beforebegin',compactBar);
      else timerHost.appendChild(compactBar);

      compactBar.querySelectorAll('[data-estudei-cat]').forEach(btn=>{
        btn.addEventListener('click',()=>{
          const c=getEstudeiCycleState();
          c.activeCategory=btn.getAttribute('data-estudei-cat')||'teoria';
          saveEstudeiCycleState(c);
          renderEstudeiCycleWidget();
        });
      });
    }

    // 2) No card "Plano diário" (#dailyPlan): exibe a Fila de Rotação de Disciplinas do Edital Sincronizado (100% alinhada à Missão Diária e sem buraco no layout!)
    const planEl=document.querySelector('#dailyPlan');
    const planCard=planEl?.closest('.card');
    if(planCard){
      const existingCycle=planCard.querySelector('#estudeiCycleWidget');
      if(existingCycle)existingCycle.remove();
      const box=document.createElement('div');
      box.id='estudeiCycleWidget';
      box.style.cssText='margin-bottom:12px;padding:12px 14px;border-radius:14px;background:linear-gradient(135deg,rgba(8,22,38,0.95),rgba(12,30,52,0.9));border:1px solid rgba(56,189,248,0.32);';
      function getSubjectAccuracyAndWeight(subj) {
        const scores=(state?.scores||[]).filter(s=>!s.campaignId||s.campaignId===state?.activeCampaignId);
        const subjScores=scores.filter(s=>{
          const m=missions.find(x=>x.id===s.id);
          return m&&subjectKey(canonicalSubjectName(m.subject))===subjectKey(subj);
        });
        const tot=subjScores.reduce((n,s)=>n+Number(s.total||0),0);
        const cor=subjScores.reduce((n,s)=>n+Number(s.correct||0),0);
        const acc=tot>=3?Math.round((cor/tot)*100):null;
        const pendingCnt=missions.filter(m=>subjectKey(canonicalSubjectName(m.subject))===subjectKey(subj)&&!state?.done?.[m.id]).length;
        const needsDouble=(acc!==null&&acc<65)||pendingCnt>=8;
        return {acc,pendingCnt,weight:needsDouble?2:1};
      }
      const pillsHtml=editalSubjects.map((subj,idx)=>{
        const isCurrent=idx===activeIdx;
        const sw=getSubjectAccuracyAndWeight(subj);
        const accTag=sw.acc!==null?` · ${sw.acc}%`:'';
        const wTag=st.weightedMode&&sw.weight===2?' 🔥2x':'';
        return `<button type="button" data-cycle-pick-subj="${escText(subj)}" class="ghost small" style="width:auto;min-height:30px;padding:4px 10px;font-size:11.5px;border-radius:999px;${isCurrent?'background:rgba(56,189,248,0.2);border-color:#38bdf8;color:#fff;font-weight:800;':'opacity:0.85;'}" title="${sw.weight===2?'Prioridade Dobrada (2 blocos por volta do ciclo)':'Ritmo Normal (1 bloco por volta)'}">${idx+1}. ${escText(subj)}${accTag}${wTag}${isCurrent?' (Atual)':''}</button>`;
      }).join('');
      box.innerHTML=`
        <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px;">
          <div>
            <span class="eyebrow" style="color:#38bdf8;">🔄 CICLO TÁTICO DO SEU EDITAL · BLOCO #${(st.completedBlocks||0)+1}</span>
            <div style="font-weight:800;font-size:14.5px;color:var(--text,#f8fafc);margin-top:2px;">🎯 Matéria em Foco: <span style="color:#38bdf8;">${escText(currSubject)}</span></div>
            <div class="small muted" style="margin-top:2px;">Assunto da vez: <b>${escText(currTopicName)}</b> · ⏭️ Próxima da fila: <b>${escText(nextSubject)}</b></div>
          </div>
          <div style="display:flex;gap:6px;flex-wrap:wrap;">
            <button type="button" id="startEstudeiBlockNowBtn" class="action small" style="width:auto;padding:7px 12px;font-size:12px;">📖 1. Abrir Resumo</button>
            <button type="button" id="practiceEstudeiBlockBtn" class="ghost small" style="width:auto;padding:7px 12px;font-size:12px;border-color:rgba(52,211,153,0.45);color:#6ee7b7;">🎯 2. Questões</button>
            <button type="button" id="advanceEstudeiCycleBtn" class="ghost small" style="width:auto;padding:7px 12px;font-size:12px;border-color:rgba(56,189,248,0.45);">⏭️ Girar para Próxima Matéria</button><button type="button" id="balanceEstudeiCycleByWeightBtn" class="ghost small" style="width:auto;padding:7px 12px;font-size:12px;border-color:rgba(245,158,11,0.45);color:#fcd34d;" title="Prioriza com peso 2x as disciplinas do edital em que seu acerto está abaixo de 65%">⚖️ ${st.weightedMode?'Ciclo Ponderado 2x (Ativo)':'Balancear por Peso & Desempenho'}</button>
          </div>
        </div>
        <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;padding-top:8px;border-top:1px solid rgba(148,163,184,0.15);">
          <span class="small muted" style="font-size:11px;margin-right:2px;">Ordem das matérias do seu edital:</span>
          ${pillsHtml}
        </div>
      `;
      planEl.insertAdjacentElement('beforebegin',box);

      box.querySelectorAll('[data-cycle-pick-subj]').forEach(btn=>{
        btn.addEventListener('click',()=>{
          const chosen=btn.getAttribute('data-cycle-pick-subj');
          const c=getEstudeiCycleState();
          c.customSubject=chosen;
          saveEstudeiCycleState(c);
          if(!switchDailyMissionToSubject(chosen))renderEstudeiCycleWidget();
          if(typeof toast==='function')toast(`🎯 Missão Diária e Ciclo sincronizados em: ${chosen}`);
        });
      });

      box.querySelector('#startEstudeiBlockNowBtn')?.addEventListener('click',()=>{
        const studyNav=document.querySelector('[data-view="study"]')||document.querySelector('.tab[data-tab="study"]');
        if(studyNav)studyNav.click();
        else if(typeof renderViewById==='function')renderViewById('study',true);
        setTimeout(()=>{
          const sf=document.querySelector('#summaryFilter');
          if(sf){
            const matchOpt=[...sf.options].find(o=>subjectKey(o.value)===subjectKey(currSubject));
            if(matchOpt){sf.value=matchOpt.value;sf.dispatchEvent(new Event('change'));}
          }
        },60);
        if(typeof toast==='function')toast(`📖 Abrindo resumos de ${currSubject}!`);
      });

      box.querySelector('#practiceEstudeiBlockBtn')?.addEventListener('click',()=>{
        const qNav=document.querySelector('[data-view="report"]')||document.querySelector('.tab[data-tab="report"]');
        if(qNav)qNav.click();
        else if(typeof renderViewById==='function')renderViewById('report',true);
        setTimeout(()=>{
          const qSubj=document.querySelector('#questionSubject');
          if(qSubj){
            const matchOpt=[...qSubj.options].find(o=>subjectKey(o.value)===subjectKey(currSubject));
            if(matchOpt){qSubj.value=matchOpt.value;qSubj.dispatchEvent(new Event('change'));}
          }
        },60);
        if(typeof toast==='function')toast(`🎯 Bateria filtrada em ${currSubject}!`);
      });

      box.querySelector('#advanceEstudeiCycleBtn')?.addEventListener('click',()=>{
        const c=getEstudeiCycleState();
        c.completedBlocks=(c.completedBlocks||0)+1;
        c.customSubject=nextSubject;
        saveEstudeiCycleState(c);
        if(!switchDailyMissionToSubject(nextSubject))renderEstudeiCycleWidget();
        if(typeof toast==='function')toast(`✓ Ciclo girado para ${nextSubject}! Missão Atual e Cronômetro sincronizados.`);
      });
      box.querySelector('#balanceEstudeiCycleByWeightBtn')?.addEventListener('click',()=>{
        const c=getEstudeiCycleState();
        c.weightedMode=!c.weightedMode;
        // Se ativou o balanceamento por desempenho, encontra a matéria com menor taxa de acerto (<65%) ou mais pendências
        if(c.weightedMode&&editalSubjects.length>1){
          const ranked=[...editalSubjects].map(s=>({s,...getSubjectAccuracyAndWeight(s)})).sort((a,b)=>(a.acc??60)-(b.acc??60)||(b.pendingCnt-a.pendingCnt));
          if(ranked[0]?.s){
            c.customSubject=ranked[0].s;
            saveEstudeiCycleState(c);
            switchDailyMissionToSubject(ranked[0].s);
            if(typeof toast==='function')toast(`⚖️ Ciclo Ponderado 2x ativado! Priorizando reforço em ${ranked[0].s}.`);
            return;
          }
        }
        saveEstudeiCycleState(c);
        renderEstudeiCycleWidget();
        if(typeof toast==='function')toast(c.weightedMode?'⚖️ Ciclo Ponderado 2x ativado (matérias < 65% ganham 2 blocos por volta)!':'🔄 Ciclo voltou para rotação simples 1x.');
      });
    }
  }

  function renderEstudeiEditalThermometer(){
    if(typeof document==='undefined')return;
    const mapSection=document.querySelector('#map');
    if(!mapSection)return;
    const existing=document.querySelector('#estudeiEditalThermometer');
    if(existing)existing.remove();
    const missions=typeof missionPool==='function'?missionPool().filter(m=>!String(m.id||'').startsWith('setup-')):[];
    const totalTopics=Math.max(1,missions.length);
    const doneTopics=missions.filter(m=>state?.done?.[m.id]).length;
    const masteredTopics=missions.filter(m=>state?.done?.[m.id]&&(typeof window.getTopicMasteryStats==="function"?window.getTopicMasteryStats(m).isMastered:false)).length;
    const theoryPct=Math.min(100,Math.round((doneTopics/totalTopics)*100));

    // Métricas 100% REAIS do progresso do usuário no edital ativo:
    const missionIdSet=new Set(missions.map(m=>m.id));
    const campScores=(Array.isArray(state?.scores)?state.scores:[]).filter(s=>!s.campaignId||s.campaignId===state?.activeCampaignId);
    const testedTopicIds=new Set(campScores.filter(s=>Number(s.total||0)>0&&missionIdSet.has(s.id)).map(s=>s.id));
    const scoreQuestionsTotal=campScores.reduce((sum,s)=>sum+Number(s.total||0),0);
    const trackedQuestionsTotal=Number(state?.questionStatsByCampaign?.[state?.activeCampaignId]?.total||0);
    const realQuestionsResolved=Math.max(scoreQuestionsTotal,trackedQuestionsTotal);
    // Cada tópico do edital requer pelo menos 1 bateria vinculada ao tópico (ou 10 questões resolvidas no portal)
    const effectiveTestedTopics=Math.min(missions.length,Math.max(testedTopicIds.size,Math.floor(realQuestionsResolved/10)));
    const practicePct=missions.length>0?Math.min(100,Math.round((effectiveTestedTopics/totalTopics)*100)):0;

    const diagMsg=doneTopics===0&&realQuestionsResolved===0
      ?'📌 Métricas reais do seu portal: conclua missões e resolva baterias de questões para avançar as duas barras.'
      :theoryPct>practicePct+15
        ?`⚠️ Você concluiu ${doneTopics} tópico(s) na teoria, mas exercitou ${effectiveTestedTopics} em questões (${realQuestionsResolved} questões resolvidas). Faça uma bateria agora!`
        :practicePct>theoryPct+15
          ?`💡 Você já resolveu ${realQuestionsResolved} questões (${effectiveTestedTopics} tópico(s) exercitados). Marque no edital os tópicos cuja teoria você já fechou!`
          :`✅ Ritmo equilibrado: ${doneTopics}/${missions.length} tópicos concluídos na teoria e ${realQuestionsResolved} questões resolvidas na prática.`;

    const card=document.createElement('div');
    card.id='estudeiEditalThermometer';
    card.className='card';
    card.style.cssText='margin-bottom:12px;border:1px solid rgba(56,189,248,0.32);background:linear-gradient(135deg,rgba(10,25,47,0.92),rgba(15,23,42,0.9));';
    card.innerHTML=`
      <div class="sectionHead" style="margin-bottom:8px;flex-wrap:wrap;gap:6px;">
        <div>
          <div class="eyebrow" style="color:#38bdf8;">TERMÔMETRO DUPLO DE COBERTURA DO EDITAL · DADOS 100% REAIS</div>
          <h3 style="margin:2px 0 0;">📊 Teoria Concluída vs. Prática Real em Questões</h3>
        </div>
        <span class="tag">📖 ${doneTopics}/${missions.length} estudados · 🏆 ${masteredTopics} dominados · 🎯 ${realQuestionsResolved}q</span>
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px;margin-bottom:8px;">
        <div>
          <div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:4px;">
            <b>📖 Teoria Estudada (${doneTopics}/${missions.length}) · 🏆 Dominados (${masteredTopics})</b>
            <span style="color:#38bdf8;font-weight:800;">${theoryPct}%</span>
          </div>
          <div class="bar"><div class="fill" style="width:${theoryPct}%;background:linear-gradient(90deg,#0284c7,#38bdf8);"></div></div>
        </div>
        <div>
          <div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:4px;">
            <b>🎯 Cobertura Prática (${effectiveTestedTopics}/${missions.length} tópicos · ${realQuestionsResolved}q)</b>
            <span style="color:#34d399;font-weight:800;">${practicePct}%</span>
          </div>
          <div class="bar"><div class="fill" style="width:${practicePct}%;background:linear-gradient(90deg,#059669,#34d399);"></div></div>
        </div>
      </div>
      <div class="small muted">${diagMsg}</div>
    `;
    const subjectsGrid=mapSection.querySelector('#subjects');
    if(subjectsGrid)subjectsGrid.insertAdjacentElement('beforebegin',card);
    else mapSection.appendChild(card);
  }

  function ensureManuaisCacadorShortcutBar(){
    // Cleanup for tabs that were opened before r175. The only entry is now Help in Menu.
    if(typeof document!=='undefined')document.querySelector('#openManuaisCacadorBtn')?.remove();
  }

  function initAllEstudeiUpgrades(){
    try{
      ensureNativePedagogicalCouplingLoaded();
      renderEstudeiCycleWidget();
      renderEstudeiEditalThermometer();
      ensureManuaisCacadorShortcutBar();
    }catch(_e){}
  }
  function creditEstudeiFocusMinutes(mins){
    if(!mins||mins<=0)return;
    const c=getEstudeiCycleState();
    const cat=c.activeCategory||'teoria';
    c.categoryMinutes=c.categoryMinutes||{};
    c.categoryMinutes[cat]=(c.categoryMinutes[cat]||0)+mins;
    saveEstudeiCycleState(c);
    renderEstudeiCycleWidget();
    if(typeof evaluateAndAutoCheckDailySteps==='function')evaluateAndAutoCheckDailySteps('focus_minutes');
  }
  window.creditEstudeiFocusMinutes=creditEstudeiFocusMinutes;
  window.initAllEstudeiUpgrades=initAllEstudeiUpgrades;
  initAllEstudeiUpgrades();
  setTimeout(initAllEstudeiUpgrades,120);
  setTimeout(initAllEstudeiUpgrades,600);
  if(typeof window!=='undefined'){
    window.addEventListener('load',initAllEstudeiUpgrades);
    document.addEventListener('click',e=>{
      if(e.target?.closest?.('[data-view], .navBtn, #reroll, #saveSettings, #timerToggle, #timerReset')){
        setTimeout(()=>{
          if(e.target?.closest?.('#reroll')){
            const c=getEstudeiCycleState();
            c.customSubject='';
            saveEstudeiCycleState(c);
          }
          initAllEstudeiUpgrades();
        },60);
      }
    });
  }

  function getNativeQuestionsForSubject(subject, boardFilter = 'all') {
    // An empty subject/board intersection must stay empty, including daily missions.
    return NATIVE_POLICE_QUESTION_BANK.filter(qItem =>
      isQuestionDisciplineEligible(qItem,subject) && questionMatchesBoardFilter(qItem,boardFilter));
  }
  window.getNativeQuestionsForSubject = getNativeQuestionsForSubject;

  // 2. Filtros Avançados (Tópico, Modo Progressivo, Inéditas/Favoritas estilo TEC/Qconcursos)
  function normalizedOrigin(question){const origin=String(question?.origin||'autoral').toLocaleLowerCase('pt-BR');return /oficial|importad|prova/.test(origin)&&!/adaptada/.test(origin)?'oficial':'autoral'}
  function normalizedDifficulty(question){const value=String(question?.difficulty||'medio').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return value.startsWith('fac')?'facil':value.startsWith('dif')?'dificil':'medio'}
  function topicKey(value){const s=String(value||'');if(!s)return'';const c=topicKey._c||(topicKey._c=new Map());if(s.length<=600){const hit=c.get(s);if(hit!==undefined)return hit}const out=s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();if(s.length<=600){if(c.size>15000)c.clear();c.set(s,out)}return out}

  const questionDisciplineCache=new WeakMap();
  function questionDisciplineDecision(item){
    const st=String(item?.statement||item?.question||''),tp=String(item?.topic||'');
    const declaredRaw=String(item?.classification_declared_subject||item?.subject||'');
    const source=String(item?.subject_source||'').toLowerCase();
    const options=Array.isArray(item?.options)?item.options:[];
    const cached=item&&typeof item==='object'?questionDisciplineCache.get(item):null;
    if(cached&&cached.st===st&&cached.tp===tp&&cached.declaredRaw===declaredRaw&&cached.source===source&&cached.category===item?.category&&cached.id===item?.id&&cached.options.length===options.length&&options.every((o,i)=>cached.options[i]===o))return cached.result;
    const valid=s=>Boolean(s&&s!=='Conteúdo Geral'&&!isInvalidTrailSubject(s));
    const declared=canonicalSubjectName(declaredRaw);
    let result;
    if(/^manual-/i.test(String(item?.id||''))||/manuais do ca[cç]ador/i.test(`${declaredRaw} ${item?.category||''}`)){
      result={subject:'Conteúdo Geral',source:'manual_da_plataforma',confidence:0,needs_review:true,reason:'Manual de uso da plataforma; fora dos treinos por disciplina.'};
    }else if(['manual','humano','humana','revisado'].includes(source)&&valid(declared)){
      result={subject:declared,source:'manual',confidence:1,needs_review:false,reason:'Disciplina confirmada por revisão humana.'};
    }else{
      // The grammatical command takes precedence over the subject of a quoted legal text.
      const command=topicKey(st);
      const grammaticalCommand=/\b(?:concordancia (?:verbal|nominal)|regencia (?:verbal|nominal)|correcao gramatical|sinal indicativo de crase|funcao sintatica|classe gramatical|colocacao pronominal|voz passiva|voz ativa|voc[aá]bulo .{0,35}classifica se|conjuncao .{0,45}(?:exprime|expressa|introduz)|pronome .{0,35}(?:refere|retoma))\b/.test(command);
      const detected=grammaticalCommand?'Língua Portuguesa':(typeof window.inferStrictQuestionSubject==='function'
        ?window.inferStrictQuestionSubject(st,tp,'Conteúdo Geral',options)
        :canonicalSubjectName('Conteúdo Geral',`${tp} ${st}`));
      const subject=valid(detected)?detected:(valid(declared)?declared:'Conteúdo Geral');
      const conflict=valid(declared)&&valid(detected)&&subjectKey(declared)!==subjectKey(detected);
      result={subject,source:valid(detected)?'heuristica':'origem',confidence:conflict?0.4:valid(detected)?0.75:valid(declared)?0.65:0,
        needs_review:conflict||!valid(subject),reason:conflict?`Disciplina declarada: ${declared}; conteúdo identificado: ${detected}. Confirme antes do treino.`:!valid(subject)?'Não foi possível identificar uma disciplina com segurança.':'Classificação automática; sujeita a conferência.'};
    }
    if(item&&typeof item==='object')questionDisciplineCache.set(item,{st,tp,declaredRaw,source,options:[...options],category:item.category,id:item.id,result});
    return result;
  }

  function isQuestionDisciplineEligible(item,subject='all'){
    if(!item||item.needs_review)return false;
    const decision=questionDisciplineDecision(item);
    return !decision.needs_review&&strictSubjectMatch(decision.subject,subject);
  }
  window.isQuestionDisciplineEligible=isQuestionDisciplineEligible;

  function resolveStrictQuestionDiscipline(qOrStmt,topic='',fallbackSubj='',options=[]){
    const item=qOrStmt&&typeof qOrStmt==='object'?qOrStmt:{statement:qOrStmt,topic,subject:fallbackSubj,options};
    return questionDisciplineDecision(item).subject;
  }
  window.resolveStrictQuestionDiscipline=resolveStrictQuestionDiscipline;

  function buildSubjectAppropriateDistractors(subjectName,correctAnswer=''){
    const sk=topicKey(canonicalSubjectName(subjectName||''));
    let pool=[];
    if(/raciocinio|logico|rlm|matematica/.test(sk)){
      pool=[
        'A proposição composta apresentada configura uma contradição lógica independentemente dos valores lógicos atribuídos às proposições simples.',
        'O valor lógico da condicional (se... então) torna-se falso quando o antecedente é falso e o consequente é verdadeiro.',
        'Pelas regras de equivalência lógica e pelas Leis de De Morgan, a conclusão depende da falsidade simultânea de todas as premissas.',
        'Não é possível determinar o valor lógico da conclusão a partir das premissas fornecidas na estrutura argumentativa.'
      ];
    }else if(/portugues/.test(sk)){
      pool=[
        'A substituição proposta preservaria o sentido original, mas acarretaria prejuízo à correção gramatical por violar a regência verbal padrão.',
        'O emprego do sinal indicativo de crase seria obrigatório mesmo diante de verbo no infinitivo ou pronome indefinido.',
        'A forma verbal destacada deveria ser flexionada no plural para concordar com o termo preposicionado adjacente.',
        'O conectivo empregado introduz relação semântica de proporção, não admitindo comutação sem alteração sintática.'
      ];
    }else if(/informatica/.test(sk)){
      pool=[
        'O recurso descrito executa a formatação física da partição do sistema operacional sem preservar cópias de segurança em nuvem.',
        'O protocolo mencionado opera exclusivamente na camada física para criptografia assimétrica de planilhas locais.',
        'O atalho de teclado indicado encerra imediatamente todos os processos em segundo plano do navegador sem confirmação.',
        'A ferramenta atua como um malware do tipo ransomware ao bloquear portas de rede autorizadas pelo firewall.'
      ];
    }else if(/historia|geografia/.test(sk)){
      pool=[
        'O movimento teve caráter exclusivamente pacífico e contou com apoio irrestrito da Coroa Portuguesa desde sua origem.',
        'O episódio ocorreu apenas no final do século XX, sem relação com as disputas políticas e econômicas do período colonial ou imperial.',
        'A liderança do movimento defendia a manutenção integral do monopólio comercial europeu e a centralização absolutista.',
        'O fenômeno restringiu-se às áreas metropolitanas do Sul do país, sem impacto histórico ou territorial em Pernambuco.'
      ];
    }else{
      pool=[
        'Alternativa incorreta conforme a literalidade da norma de regência e o entendimento consolidado sobre a matéria.',
        'Hipótese vedada pelo ordenamento jurídico ou incompatível com os requisitos legais aplicáveis ao caso.',
        'Conceito pertencente a instituto diverso, invertendo a regra geral e a exceção previstas no dispositivo legal.',
        'A medida dependeria exclusivamente de autorização judicial prévia, sendo vedada sua aplicação imediata em qualquer hipótese.'
      ];
    }
    return pool.filter(d=>topicKey(d)!==topicKey(correctAnswer));
  }
  window.buildSubjectAppropriateDistractors=buildSubjectAppropriateDistractors;

  function isTopicContaminatedByWrongSubject(topicStr,realSubj){
    const t=String(topicStr||'').trim();
    if(!t)return true;
    if(/^(?:direito constitucional geral|direito penal geral|direito processual penal|lingua portuguesa|raciocinio logico|geral|edital|regras do edital|quest[aã]o\s*\d+|item\s*\d+|simulado.*|corre[cç][aã]o de erro|ponto de aten[cç][aã]o|conte[uú]do.*)$/i.test(t)){
      const tSubj=canonicalSubjectName(t);
      if(tSubj&&tSubj!=='Conteúdo Geral'&&topicKey(tSubj)!==topicKey(realSubj))return true;
      if(/^(?:geral|edital|regras do edital|quest[aã]o\s*\d+|item\s*\d+|simulado.*)$/i.test(t))return true;
    }
    return false;
  }

  function sanitizeAllQuestionsAndErrorsSubjects(force=false){
    if(typeof purgeHunterManualStudyArtifacts==='function')purgeHunterManualStudyArtifacts();
    if(typeof ensureNativeQuestionBankLoaded==='function')ensureNativeQuestionBankLoaded();
    const qArr=Array.isArray(ALL_QUESTIONS)?ALL_QUESTIONS:[];
    const errObj=(typeof state==='object'&&state?.errors&&typeof state.errors==='object')?state.errors:null;
    const campId=(typeof state==='object'&&state?.activeCampaignId)||'default';
    const missionsLen=(typeof state==='object'&&Array.isArray(state?.customCampaign?.missions))?state.customCampaign.missions.length:0;
    const sig=`${qArr.length}|${errObj?Object.keys(errObj).length:0}|${campId}|${missionsLen}|${qArr[0]?.statement?.slice(0,20)||''}|${qArr[qArr.length-1]?.statement?.slice(0,20)||''}`;
    if(!force&&sanitizeAllQuestionsAndErrorsSubjects._lastArray===qArr&&sanitizeAllQuestionsAndErrorsSubjects._lastSig===sig)return;
    sanitizeAllQuestionsAndErrorsSubjects._lastArray=qArr;
    const isValidFn=typeof window.isValidPedagogicalQuestion==='function'?window.isValidPedagogicalQuestion:(()=>true);
    const byStmt=new Map();
    if(Array.isArray(ALL_QUESTIONS)){
      for(let i=ALL_QUESTIONS.length-1;i>=0;i--){
        const qItem=ALL_QUESTIONS[i];
        if(!qItem||typeof qItem!=='object'||(typeof isPlatformManualStudyArtifact==='function'&&isPlatformManualStudyArtifact(qItem))||!isValidFn(qItem)){
          ALL_QUESTIONS.splice(i,1);
          continue;
        }
        const decision=questionDisciplineDecision(qItem);
        const realSubj=decision.subject;
        if(decision.needs_review&&!qItem.classification_declared_subject)qItem.classification_declared_subject=qItem.subject||'';
        qItem.classification_needs_review=decision.needs_review;
        qItem.classification_reason=decision.reason;
        if(realSubj&&!isInvalidTrailSubject(realSubj)&&realSubj!==qItem.subject){
          qItem.subject=realSubj;
        }
        if(isTopicContaminatedByWrongSubject(qItem.topic,qItem.subject)&&typeof inferQuestionPedagogicalTopic==='function'){
          qItem.topic=inferQuestionPedagogicalTopic(qItem.statement,qItem.subject);
        }
        qItem.subject_canonical=subjectKey(qItem.subject||'');
        qItem.topic_canonical=topicKey(qItem.topic||'');
        if(!qItem._hayKey||qItem._hayTopicSrc!==qItem.topic){
          qItem._hayKey=topicKey(`${qItem.topic||''} ${qItem.statement||''}`);
          qItem._hayTopicSrc=qItem.topic;
        }
        if(qItem.learning_order===undefined||qItem._loCampId!==campId){
          qItem.learning_order=computeQuestionEditalLearningOrder(qItem);
          qItem._loCampId=campId;
        }
        const stKey=topicKey(qItem.statement||'');
        if(stKey&&stKey.length>=15&&!byStmt.has(stKey))byStmt.set(stKey,qItem);
      }
      dedupeAllQuestionsInMemory();
    }
    if(state?.customQuestionsByCampaign&&typeof state.customQuestionsByCampaign==='object'){
      for(const [cId,list] of Object.entries(state.customQuestionsByCampaign)){
        if(!Array.isArray(list))continue;
        state.customQuestionsByCampaign[cId]=list.filter(qItem=>qItem&&typeof qItem==='object'&&isValidFn(qItem)).map(qItem=>{
          const decision=questionDisciplineDecision(qItem);
          const realSubj=decision.subject;
          if(decision.needs_review&&!qItem.classification_declared_subject)qItem.classification_declared_subject=qItem.subject||'';
          qItem.classification_needs_review=decision.needs_review;
          qItem.classification_reason=decision.reason;
          if(realSubj&&!isInvalidTrailSubject(realSubj))qItem.subject=realSubj;
          if(isTopicContaminatedByWrongSubject(qItem.topic,qItem.subject)&&typeof inferQuestionPedagogicalTopic==='function'){
            qItem.topic=inferQuestionPedagogicalTopic(qItem.statement,qItem.subject);
          }
          return qItem;
        });
      }
    }
    if(state?.errors&&typeof state.errors==='object'){
      let errChanged=false;
      for(const [errKey,err] of Object.entries(state.errors)){
        if(typeof isPlatformManualStudyArtifact==='function'&&isPlatformManualStudyArtifact({...err,id:errKey}))continue;
        if(!err||typeof err!=='object'){
          delete state.errors[errKey];
          errChanged=true;
          continue;
        }
        if(err.question){
          const testObj={statement:err.question,options:Array.isArray(err.options)&&err.options.length>=2?err.options:['Opção A','Opção B'],topic:err.topic||'',associated_text:err.associated_text||''};
          if(!isValidFn(testObj)){
            delete state.errors[errKey];
            errChanged=true;
            continue;
          }
        }
        if(/^(?:edital|regras do edital|instru[cç][oõ]es da prova|converg[eê]ncia lingu[ií]stica)$/i.test(String(err.topic||'').trim())&&!err.associated_text&&String(err.question||'').length<220){
          delete state.errors[errKey];
          errChanged=true;
          continue;
        }
        const stKey=topicKey(err.question||'');
        const matchedQ=stKey?byStmt.get(stKey):null;
        if(matchedQ){
          if(err.subject!==matchedQ.subject){err.subject=matchedQ.subject;errChanged=true;}
          if(matchedQ.topic&&(isTopicContaminatedByWrongSubject(err.topic,matchedQ.subject)||err.topic!==matchedQ.topic)){err.topic=matchedQ.topic;errChanged=true;}
          if(Array.isArray(matchedQ.options)&&matchedQ.options.length>=2){
            err.options=[...matchedQ.options];
            err.correct_index=matchedQ.correct_index;
          }
        }else if(err.question||err.topic){
          const realErrSubj=resolveStrictQuestionDiscipline(err.question||'',err.topic||'',err.subject||'',err.options||[]);
          if(realErrSubj&&!isInvalidTrailSubject(realErrSubj)&&err.subject!==realErrSubj){
            err.subject=realErrSubj;
            errChanged=true;
          }
          if(isTopicContaminatedByWrongSubject(err.topic,err.subject)&&typeof inferQuestionPedagogicalTopic==='function'){
            err.topic=inferQuestionPedagogicalTopic(err.question||'',err.subject);
            errChanged=true;
          }
        }
      }
      if(errChanged&&typeof save==='function')save();
    }
    const afterArr=Array.isArray(ALL_QUESTIONS)?ALL_QUESTIONS:[];
    sanitizeAllQuestionsAndErrorsSubjects._lastSig=`${afterArr.length}|${errObj?Object.keys(errObj).length:0}|${campId}|${missionsLen}|${afterArr[0]?.statement?.slice(0,20)||''}|${afterArr[afterArr.length-1]?.statement?.slice(0,20)||''}`;
  }
  window.sanitizeAllQuestionsAndErrorsSubjects=sanitizeAllQuestionsAndErrorsSubjects;

  function strictSubjectMatch(questionSubject,filterSubject){
    if(!filterSubject||filterSubject==='all')return true;
    const q=canonicalSubjectName(questionSubject||'');
    const f=canonicalSubjectName(filterSubject||'');
    if(!q||q==='Conteúdo Geral'||isInvalidTrailSubject(q))return false;
    return subjectKey(q)===subjectKey(f);
  }
  window.strictSubjectMatch=strictSubjectMatch;

  function computeQuestionEditalLearningOrder(qItem){
    const missions=typeof orderedMissions==='function'?orderedMissions():(typeof missionPool==='function'?missionPool():[]);
    if(!missions.length)return Number(qItem?.learning_order??9999);
    const qSubjKey=subjectKey(qItem?.subject||'');
    const subjMissions=missions.filter(m=>subjectKey(canonicalSubjectName(m?.subject||''))===qSubjKey);
    for(let i=0;i<subjMissions.length;i++){
      const m=subjMissions[i];
      if(questionMatchesTopicFilter(qItem,topicKey(m.name||''),qItem.subject,m.name||'')){
        return Number(m.learningOrder??m.editalOrder??i);
      }
    }
    if(subjMissions.length){
      return Number(subjMissions[0].learningOrder??subjMissions[0].editalOrder??500)+50;
    }
    return Number(qItem?.learning_order??9999);
  }
  window.computeQuestionEditalLearningOrder=computeQuestionEditalLearningOrder;

  function findDuplicateQuestions(list=ALL_QUESTIONS||[]){
    const seen=new Map();
    const dups=[];
    list.forEach((qItem,idx)=>{
      if(!qItem)return;
      qItem.subject_canonical=subjectKey(qItem.subject||'');
      qItem.topic_canonical=topicKey(qItem.topic||'');
      if(qItem.learning_order===undefined||qItem.learning_order===9999){
        qItem.learning_order=computeQuestionEditalLearningOrder(qItem);
      }
      const stKey=topicKey(qItem.statement||'');
      const fp=questionFingerprint(qItem);
      const dedupKey=stKey.length>=24?`${qItem.subject_canonical}|${stKey}`:fp;
      if(seen.has(dedupKey)){
        dups.push({idx,firstIdx:seen.get(dedupKey),fp,preview:String(qItem.statement||'').slice(0,80)});
      }else{
        seen.set(dedupKey,idx);
      }
    });
    return dups;
  }
  window.findDuplicateQuestions=findDuplicateQuestions;

  function dedupeAllQuestionsInMemory(){
    if(!Array.isArray(ALL_QUESTIONS)||!ALL_QUESTIONS.length)return 0;
    const dups=findDuplicateQuestions(ALL_QUESTIONS);
    if(!dups.length)return 0;
    const removeSet=new Set(dups.map(d=>d.idx));
    for(let i=ALL_QUESTIONS.length-1;i>=0;i--){
      if(removeSet.has(i))ALL_QUESTIONS.splice(i,1);
    }
    return removeSet.size;
  }
  window.dedupeAllQuestionsInMemory=dedupeAllQuestionsInMemory;

  // === Maestria por Tópico + XP Honesto (v103 Server RPC + Fallback Local) ===
  function updateLocalTopicMastery(subject,topic,isCorrect){
    if(typeof state!=='object'||!state)return null;
    state.topicMastery=state.topicMastery||{};
    const campId=state.activeCampaignId||'default';
    const sKey=subjectKey(canonicalSubjectName(subject||'geral'))||'geral';
    const tKey=topicKey(topic||'geral')||'geral';
    const mKey=`${campId}|${sKey}|${tKey}`;
    const prev=state.topicMastery[mKey]||{attempts:0,correct:0,mastery:0,bonus70Paid:false,bonus85Paid:false};
    const attempts=Number(prev.attempts||0)+1;
    const correct=Number(prev.correct||0)+(isCorrect?1:0);
    const mastery=attempts<5
      ?Number(((correct/Math.max(1,attempts))*100*(attempts/5)).toFixed(2))
      :Number(((correct/attempts)*100).toFixed(2));
    let bonus70Paid=Boolean(prev.bonus70Paid);
    let bonus85Paid=Boolean(prev.bonus85Paid);
    let masteryBonus=0;
    if(isCorrect&&attempts>=8){
      if(mastery>=85&&!bonus85Paid){
        masteryBonus=15;
        bonus85Paid=true;
        bonus70Paid=true;
      }else if(mastery>=70&&!bonus70Paid){
        masteryBonus=8;
        bonus70Paid=true;
      }
    }
    state.topicMastery[mKey]={attempts,correct,mastery,bonus70Paid,bonus85Paid,subjectKey:sKey,topicKey:tKey,lastAttemptAt:new Date().toISOString()};
    return {mastery,attempts,correct,mastery_bonus:masteryBonus,subject_key:sKey,topic_key:tKey};
  }
  window.updateLocalTopicMastery=updateLocalTopicMastery;

  function applyXpLocal(amount,reason=''){
    if(!amount||amount<=0||typeof state!=='object'||!state)return;
    state.learning=state.learning||{};
    state.learning.xp=(Number(state.learning.xp)||0)+amount;
    if(reason){
      state.learning.xpLog=Array.isArray(state.learning.xpLog)?state.learning.xpLog:[];
      state.learning.xpLog.push({at:new Date().toISOString(),amount,reason});
      if(state.learning.xpLog.length>50)state.learning.xpLog.shift();
    }
    if(typeof save==='function')save();
    if(typeof renderHero==='function')renderHero();
  }
  window.applyXpLocal=applyXpLocal;

