  function populateTopicFilter(){
    ensureTopicFilterSelect();
    sanitizeAllQuestionsAndErrorsSubjects();
    const topicSelect=q('#questionTopic');
    if(!topicSelect)return;
    const subject=q('#questionSubject')?.value||'all';
    const board=q('#questionBoardFilter')?.value||'all';
    const currentTopic=topicSelect.value||'all';
    const subjKey=subject==='all'?'all':topicKey(canonicalSubjectName(subject));
    const topicSignature=JSON.stringify([state.activeCampaignId,subject,board,
      (typeof orderedMissions==='function'?orderedMissions():[]).map(m=>[m.id,m.subject,m.name]),
      (ALL_QUESTIONS||[]).map(item=>[item.subject_canonical,item.topic_canonical,item.topic,item.board,item.statement])]);
    if(topicSelect._sourceSignature===topicSignature)return;
    const bySubjBucket=new Map();
    const byTopicCount=new Map();
    const byTopicSample=new Map();
    const allForSubject=[];
    for(const item of (ALL_QUESTIONS||[])){
      if(typeof isQuestionDisciplineEligible==='function'&&!isQuestionDisciplineEligible(item,subject))continue;
      const itemSubjKey=item.subject_canonical||topicKey(resolveStrictQuestionDiscipline(item));
      if(subjKey!=='all'&&itemSubjKey!==subjKey)continue;
      if(!questionMatchesBoardFilter(item,board))continue;
      allForSubject.push(item);
      let sArr=bySubjBucket.get(itemSubjKey);
      if(!sArr){sArr=[];bySubjBucket.set(itemSubjKey,sArr);}
      sArr.push(item);
      const tKey=topicKey(item.topic||'');
      if(tKey){
        byTopicCount.set(tKey,(byTopicCount.get(tKey)||0)+1);
        if(!byTopicSample.has(tKey))byTopicSample.set(tKey,item);
      }
    }
    const editalMissions=(typeof orderedMissions==='function'?orderedMissions():(typeof missionPool==='function'?missionPool():[])).filter(m=>m&&m.name&&!String(m.id||'').startsWith('setup-')&&(subjKey==='all'||topicKey(canonicalSubjectName(m.subject))===subjKey));
    const entries=[];
    const seenKeys=new Set();
    // 1) Tópicos do Edital em Ordem Cronológica Estrita (1 -> 2 -> 3...) comparando apenas com questões da própria disciplina (O(1) bucket)
    editalMissions.forEach((m,idx)=>{
      const rawName=String(m.name||'').trim();
      const numPrefix=/^\d+[.)\s-]/.test(rawName)?'':`${idx+1}. `;
      const displayLabel=`${numPrefix}${rawName}`;
      const k=topicKey(rawName);
      if(!k||seenKeys.has(k))return;
      seenKeys.add(k);
      const mSubjKey=topicKey(canonicalSubjectName(m.subject||''));
      const candidateQs=subjKey==='all'?(bySubjBucket.get(mSubjKey)||[]):allForSubject;
      let matchCnt=0;
      for(let i=0;i<candidateQs.length;i++){
        if(questionMatchesTopicFilter(candidateQs[i],k,m.subject||subject,rawName))matchCnt++;
      }
      entries.push([k,`${shortLabel(displayLabel,48)} (${matchCnt}q)`]);
    });
    // 2) Subtópicos únicos das questões (itera apenas sobre os ~35 tópicos únicos em byTopicSample, nunca sobre 1.070 questões)
    const extraTopicsMap=new Map();
    for(const [key,sampleItem] of byTopicSample.entries()){
      if(seenKeys.has(key))continue;
      const label=String(sampleItem?.topic||'').trim();
      if(!label||isTopicContaminatedByWrongSubject(label,subject==='all'?sampleItem.subject:subject))continue;
      const sampleSubjKey=sampleItem.subject_canonical||topicKey(sampleItem.subject||'');
      const covered=editalMissions.some(m=>topicKey(canonicalSubjectName(m.subject||''))===sampleSubjKey&&questionMatchesTopicFilter(sampleItem,topicKey(m.name),sampleItem.subject,m.name));
      if(covered)continue;
      extraTopicsMap.set(key,label);
    }
    const extractOrderNum=str=>{
      const m=String(str||'').match(/(?:^|\b(?:art(?:igo)?s?|lei)\.?\s*)(\d{1,4})/i);
      return m?Number(m[1]):9999;
    };
    const sortedExtras=[...extraTopicsMap.entries()].sort((a,b)=>{
      const na=extractOrderNum(a[1]),nb=extractOrderNum(b[1]);
      if(na!==nb)return na-nb;
      return a[1].localeCompare(b[1],'pt-BR');
    });
    for(const [k,label] of sortedExtras){
      seenKeys.add(k);
      const cnt=byTopicCount.get(k)||0;
      entries.push([k,`${shortLabel(label,48)} (${cnt}q)`]);
    }
    topicSelect._sourceSignature=topicSignature;
    topicSelect.innerHTML='<option value="all">Todos os assuntos da disciplina (Ordem Cronológica)</option>'+entries.map(([key,label])=>`<option value="${escText(key)}" title="${escText(label)}">${escText(label)}</option>`).join('');
    topicSelect.value=seenKeys.has(currentTopic)?currentTopic:'all';
    populateExamHubSelects();
  }

  function filteredQuestionPool(){
    ensureNativeQuestionBankLoaded();
    sanitizeAllQuestionsAndErrorsSubjects();
    const subject=q('#questionSubject')?.value||'all',board=q('#questionBoardFilter')?.value||'all',topic=q('#questionTopic')?.value||'all',difficulty=q('#questionDifficulty')?.value||'all',origin=q('#questionOrigin')?.value||'all',battleMode=q('#questionBattleMode')?.value||'progressive',historyFilter=q('#questionHistoryFilter')?.value||'all';
    const allMatchingSubject=(ALL_QUESTIONS||[]).filter(item=>isQuestionDisciplineEligible(item,subject));
    const source=allMatchingSubject.length?allMatchingSubject:(typeof questionsForMode==='function'?questionsForMode('battle',subject).filter(item=>isQuestionDisciplineEligible(item,subject)):[]);
    const topicSel=q('#questionTopic');
    const selectedTopicLabel=topicSel&&topicSel.selectedIndex>=0?topicSel.options[topicSel.selectedIndex]?.text||'':'';
    let byTopic=source.filter(item=>questionMatchesBoardFilter(item,board)&&(topic==='all'||questionMatchesTopicFilter(item,topic,subject,selectedTopicLabel))&&(difficulty==='all'||normalizedDifficulty(item)===difficulty)&&(origin==='all'||normalizedOrigin(item)===origin));
    let filtered=byTopic.filter(item => !["sem_gabarito", "anulada"].includes(answerKeyStatus(item)));
    if(historyFilter==='unanswered'){
      const unanswered=filtered.filter(item=>!isQuestionAnsweredBefore(item));
      filtered=unanswered;
    }else if(historyFilter==='wrong'){
      const errEntries=activeCampaignErrors();
      filtered=filtered.filter(item=>questionMatchesErrorPool(item,errEntries));
    }else if(historyFilter==='correct'){
      const errEntries=activeCampaignErrors();
      filtered=filtered.filter(item=>isQuestionAnsweredBefore(item)&&!questionMatchesErrorPool(item,errEntries));
    }else if(historyFilter==='favorites'){
      filtered=filtered.filter(item=>isQuestionFavorited(item));
    }
    if(battleMode==='errors'){
      const errEntries=activeCampaignErrors();
      const errPool=filtered.filter(item=>questionMatchesErrorPool(item,errEntries));
      filtered=errPool;
    }
    // Filtro estrito quando disciplina específica está selecionada
    filtered=filtered.filter(item=>isQuestionDisciplineEligible(item,subject));
    // Ordenação pedagógica cronológica do edital (learning_order -> topic_canonical -> origem)
    const followOrder=q('#followEditalOrderToggle')?q('#followEditalOrderToggle').checked:true;
    if(followOrder){
      filtered=[...filtered].sort((a,b)=>{
        const loA=Number(a.learning_order??computeQuestionEditalLearningOrder(a));
        const loB=Number(b.learning_order??computeQuestionEditalLearningOrder(b));
        if(loA!==loB)return loA-loB;
        const tA=topicKey(a.topic_canonical||a.topic||'');
        const tB=topicKey(b.topic_canonical||b.topic||'');
        if(tA!==tB)return tA.localeCompare(tB,'pt-BR');
        return difficultyWeight(normalizedDifficulty(a))-difficultyWeight(normalizedDifficulty(b));
      });
    }
    return filtered;
  }

  function updateQuestionPool(){
    const pool=filteredQuestionPool(),badge=q('#questionPoolCount'),battleMode=q('#questionBattleMode')?.value||'progressive';
    if(badge)badge.textContent=`${pool.length} disponíve${pool.length===1?'l':'is'}`;
    const button=q('#startQuestions');
    if(button){
      button.disabled=!pool.length;
      const count=Math.min(battleMode==='progressive'?6:5,pool.length);
      button.textContent=pool.length
        ? (battleMode==='progressive'?`Iniciar Desafio Progressivo (${count} questões)`:battleMode==='errors'?`Iniciar Reforço de Erros (${count} questões)`:`Iniciar batalha de ${count} questões`)
        : 'Nenhuma questão neste filtro';
    }
    const errBtn=q('#startErrorReinforcementBtn');
    if(errBtn){
      const errCount=activeCampaignErrors().length;
      errBtn.textContent=`🔥 Reforçar meus erros (${errCount})`;
    }
    updateSimuladoAvailability();
  }

  function progressiveQuestions(pool,count=6){
    const groups={
      facil:shuffle(pool.filter(item=>normalizedDifficulty(item)==='facil')),
      medio:shuffle(pool.filter(item=>normalizedDifficulty(item)==='medio')),
      dificil:shuffle(pool.filter(item=>normalizedDifficulty(item)==='dificil'))
    };
    const ordered=[];
    const pattern=['facil','facil','medio','medio','dificil','dificil'];
    for(const diff of pattern){
      const candidate=groups[diff].shift();
      if(candidate&&!ordered.includes(candidate))ordered.push(candidate);
    }
    for(const item of [...groups.facil,...groups.medio,...groups.dificil,...shuffle(pool)]){
      if(ordered.length>=count)break;
      if(!ordered.includes(item))ordered.push(item);
    }
    return ordered.slice(0,count).sort((a,b)=>difficultyWeight(normalizedDifficulty(a))-difficultyWeight(normalizedDifficulty(b)));
  }

  function startFilteredBattle(){
    const pool=filteredQuestionPool(),subject=q('#questionSubject')?.value||'all',topicSel=q('#questionTopic'),battleMode=q('#questionBattleMode')?.value||'progressive';
    if(!pool.length)return toast('Não há questões que correspondam aos filtros selecionados.');
    const topicLabel=topicSel&&topicSel.value!=='all'?topicSel.options[topicSel.selectedIndex]?.text:'';
    const count=Math.min(battleMode==='progressive'?6:5,pool.length);
    const chosenQuestions=(battleMode==='progressive'?progressiveQuestions(pool,count):balancedQuestions(pool,count)).map(prepareQuestion);
    activeQuestions={
      mode:battleMode==='progressive'?'progressive':battleMode==='errors'?'errors':'battle',
      subject:topicLabel?`${subject==='all'?'Treino':subject} · ${topicLabel}`:subject,
      questions:chosenQuestions,
      current:0,
      correct:0,
      streak:0,
      level:1,
      answered:false
    };
    q('#questionDialogTitle').textContent=battleMode==='progressive'
      ? `Desafio Progressivo${topicLabel?` · ${topicLabel}`:''}`
      : battleMode==='errors'
      ? 'Reforço Automático de Erros'
      : topicLabel?`Batalha · ${topicLabel}`:'Batalha de questões';
    q('#questionDialog').showModal();
    showQuestion();
  }

  function startErrorReinforcementBattle(){
    const errEntries=activeCampaignErrors();
    if(!errEntries.length)return toast('Parabéns! Seu Caderno de Erros está zerado neste portal.');
    const canRetry=item=>Boolean(item&&String(item.statement||'').trim()&&isQuestionDisciplineEligible(item)&&!['sem_gabarito','anulada'].includes(answerKeyStatus(item)));
    const allPool=Array.isArray(ALL_QUESTIONS)?ALL_QUESTIONS:[];
    let errQuestions=allPool.filter(item=>canRetry(item)&&questionMatchesErrorPool(item,errEntries));
    if(!errQuestions.length){
      errQuestions=errEntries.filter(([,e])=>e?.question&&Array.isArray(e.options)).map(([key,e])=>{
        const realSubj=resolveStrictQuestionDiscipline(e.question,e.topic,e.subject,e.options);
        return {
          ...e,
          subject:realSubj||'Revisão de Erros',
          topic:e.topic||'Ponto de Atenção',
          statement:e.question,
          options:[...e.options],
          correct_index:e.correct_index,
          explanation:e.explanation||'',
          difficulty:'medio',
          origin:e.origin||'autoral',
          _alreadyPreparedConsistent:true,
          _errorNotebookKey:key
        };
      }).filter(canRetry);
    }
    if(!errQuestions.length)return toast('Estes erros não têm questões completas com gabarito válido. Use “Ler Teoria” ou importe a questão completa para refazer.');
    const count=Math.min(6,errQuestions.length);
    const questions=progressiveQuestions(errQuestions,count).map(prepareQuestion).filter(canRetry);
    if(!questions.length)return toast('As questões precisam de revisão antes do treino. Use “Ler Teoria” no Caderno de Erros.');
    activeQuestions={
      mode:'errors',
      subject:'Reforço de Erros',
      questions,
      current:0,
      correct:0,
      streak:0,
      level:1,
      answered:false
    };
    q('#questionDialogTitle').textContent='🔥 Reforço Automático de Erros';
    q('#questionDialog').showModal();
    showQuestion();
  }

  // 2B. Resolução Passo a Passo (Estilo boaResposta) + Recursos TEC / Qconcursos / Caveira / Descomplica
  function findRelatedSummary(question){
    if(!Array.isArray(ALL_SUMMARIES)||!ALL_SUMMARIES.length)return null;
    const qSubj=resolveStrictQuestionDiscipline(question);
    const qTopic=topicKey(question?.topic);
    const summaries=ALL_SUMMARIES.filter(s=>!(typeof isPlatformManualStudyArtifact==='function'?isPlatformManualStudyArtifact(s):/^manual-/i.test(String(s.id||''))||/manuais do ca[cç]ador/i.test(String(s.category||'')))&&strictSubjectMatch(s.category||s.subject,qSubj));
    return summaries.find(s=>topicKey(s.title)===qTopic||(qTopic&&` ${topicKey(s.title)} `.includes(` ${qTopic} `)))
      || summaries[0]
      || null;
  }

  function buildSpecificErrorDiagnosis(item,chosenIndex,correctIndex,isCE){
    if(chosenIndex===correctIndex)return '';
    const opts=Array.isArray(item?.options)?item.options:[];
    const chosenText=String(opts[chosenIndex]||'').trim();
    const correctText=String(opts[correctIndex]||'').trim();
    const stmt=String(item?.statement||'').trim();
    const chosenLetter=isCE?(chosenIndex===0?'CERTO':'ERRADO'):String.fromCharCode(65+(Number(chosenIndex)>=0?chosenIndex:0));
    const correctLetter=isCE?(correctIndex===0?'CERTO':'ERRADO'):String.fromCharCode(65+(Number(correctIndex)>=0?correctIndex:0));
    if(chosenIndex===-2){
      return `Você deixou a questão em branco (estratégia líquida). O ponto central exigido pela banca está na <b>${isCE?correctLetter:'Alternativa '+correctLetter}</b>: <i>"${escText(shortLabel(correctText,160))}"</i>.`;
    }
    if(chosenIndex<0||!chosenText){
      return `O tempo esgotou antes da marcação. A resposta correta é a <b>${isCE?correctLetter:'Alternativa '+correctLetter}</b>: <i>"${escText(shortLabel(correctText,160))}"</i>.`;
    }
    const reasons=[];
    if(/\b(exceto|incorreta|incorreto|desacordo|n[aã]o\s+(?:é|são|constitui|compete|cabe)|falsa|errada)\b/i.test(stmt)){
      reasons.push(`<b>⚠️ Confira o comando:</b> o enunciado contém uma negação ou pedido de exceção. Verifique no comentário se sua escolha atende exatamente ao comando; essa pista textual, sozinha, não explica o erro.`);
    }
    const restrictMatch=chosenText.match(/\b(apenas|somente|exclusivamente|unicamente|sempre|nunca|jamais|em qualquer hip[oó]tese|em nenhuma hip[oó]tese|independentemente|imprescind[ií]vel|prescind[ií]vel|vedad[oa] em qualquer|qualquer caso|obrigatoriamente|facultativamente)\b/i);
    if(restrictMatch){
      reasons.push(`<b>🎯 Ponto para conferir:</b> a opção <b>${chosenLetter}</b> utiliza <b>"${escText(restrictMatch[1])}"</b>. Compare o alcance dessa expressão com a regra estudada. Termos absolutos também podem estar corretos; não são prova de erro.`);
    }
    const swapPairs=[
      [/\bprivativa\b/i,/\b(?:concorrente|comum|exclusiva)\b/i,'competência privativa × concorrente/comum/exclusiva'],
      [/\bconcorrente\b/i,/\b(?:privativa|comum|exclusiva)\b/i,'competência concorrente × privativa/comum/exclusiva'],
      [/\bjudici[aá]ria\b/i,/\b(?:ostensiva|administrativa)\b/i,'polícia judiciária (investigativa) × polícia ostensiva/administrativa'],
      [/\bostensiva\b/i,/\b(?:judici[aá]ria|investigativa)\b/i,'policiamento ostensivo × função de polícia judiciária'],
      [/\bhabeas\s+corpus\b/i,/\b(?:habeas\s+data|mandado\s+de\s+seguran[cç]a|mandado\s+de\s+injun[cç][aã]o|a[cç][aã]o\s+popular)\b/i,'finalidade específica de cada remédio constitucional'],
      [/\bhabeas\s+data\b/i,/\b(?:habeas\s+corpus|mandado\s+de\s+seguran[cç]a|mandado\s+de\s+injun[cç][aã]o)\b/i,'acesso/retificação de dados pessoais (Habeas Data) × direito líquido e certo / locomoção'],
      [/\bmandado\s+de\s+seguran[cç]a\b/i,/\b(?:habeas\s+corpus|habeas\s+data|mandado\s+de\s+injun[cç][aã]o|a[cç][aã]o\s+popular)\b/i,'proteção de direito líquido e certo (MS) × outros remédios constitucionais'],
      [/\breclus[aã]o\b/i,/\bdeten[cç][aã]o\b/i,'espécie de pena (reclusão × detenção)'],
      [/\bc[aâ]mara\s+dos\s+deputados\b/i,/\bsenado\s+federal\b/i,'atribuição da Câmara dos Deputados × Senado Federal']
    ];
    for(const [reA,reB,label] of swapPairs){
      if((reA.test(chosenText)&&reB.test(correctText))||(reB.test(chosenText)&&reA.test(correctText))){
        reasons.push(`<b>🔄 Conceitos para comparar:</b> as alternativas <b>${chosenLetter}</b> e <b>${correctLetter}</b> mencionam <b>${label}</b>. Consulte a fundamentação antes de concluir que houve troca conceitual.`);
        break;
      }
    }
    const chosenNums=(chosenText.match(/\b\d+\b/g)||[]).join(', ');
    const correctNums=(correctText.match(/\b\d+\b/g)||[]).join(', ');
    if(chosenNums&&correctNums&&chosenNums!==correctNums){
      reasons.push(`<b>🔢 Valores diferentes:</b> sua escolha menciona <b>${escText(chosenNums)}</b> e o gabarito indicado menciona <b>${escText(correctNums)}</b>. Confira o significado de cada número; podem representar artigos, datas ou grandezas diferentes.`);
    }
    if(!reasons.length){
      if(isCE){
        reasons.push(`<b>⚖️ Compare seu julgamento:</b> você marcou <b>${chosenLetter}</b> e o gabarito informado indica <b>${correctLetter}</b>. Consulte a explicação e a fonte de <b>"${escText(item.topic||item.subject||'Geral')}"</b> para identificar a divergência.`);
      }else{
        reasons.push(`<b>🎯 Sua escolha e o gabarito diferem:</b> compare <i>"${escText(shortLabel(chosenText,125))}"</i> com a <b>Alternativa ${correctLetter}</b> (<i>"${escText(shortLabel(correctText,125))}"</i>). A justificativa específica deve vir do comentário ou de uma fonte revisada, não desta comparação automática.`);
      }
    }
    return reasons.join('<br>');
  }
  window.buildSpecificErrorDiagnosis=buildSpecificErrorDiagnosis;

  function formatStepByStepResolution(item,chosenIndex,ok,interactive=true){
    const optsList=Array.isArray(item.options)?item.options:[];
    const keyDetails=answerKeyDetails(item);
    if(!keyDetails.scored){
      const suggested=Number(item.correct_index);
      const suggestion=keyDetails.pendingAi&&Number.isInteger(suggested)&&suggested>=0&&suggested<optsList.length?`Sugestão provisória: ${String.fromCharCode(65+suggested)}. ${String(item.explanation||'')}`:String(item.explanation||'');
      return `<div class="boaRespostaResolution"><div class="stepResolutionBlock concept"><b>${escText(keyDetails.label)}</b><p>Esta questão não gera acerto, erro, XP ou estatística de desempenho enquanto o gabarito estiver pendente.</p>${suggestion?`<p style="white-space:pre-line">${escText(suggestion)}</p>`:''}${interactive?'<button type="button" class="ghost small" id="reportQuestionIssueBtn">🚩 Validar / reportar gabarito</button>':''}</div></div>`;
    }
    const isCE=optsList.length===2&&/^certo$/i.test(String(optsList[0]||'').trim());
    const correctIndex=Number(item.correct_index)||0;
    const correctLetter=isCE?(correctIndex===0?'CERTO':'ERRADO'):String.fromCharCode(65+correctIndex);
    const chosenLetter=(Number.isInteger(chosenIndex)&&chosenIndex>=0)
      ?(isCE?(chosenIndex===0?'CERTO':'ERRADO'):String.fromCharCode(65+chosenIndex))
      :(chosenIndex===-2?'EM BRANCO (0 pt)':'TEMPO ESGOTADO');
    const rawExp=item.explanation_needs_review?'O gabarito foi alterado. O comentário anterior aguarda revisão e não deve ser usado para justificar a nova resposta.':String(item.explanation||'').trim();
    const related=findRelatedSummary(item);
    const fp=questionFingerprint(item);
    const isFav=isQuestionFavorited(item);
    const savedComment=state?.questionPersonalNotes?.[fp]||'';

    let stepsHtml = typeof window.buildFormattedResolutionStepsHtml === 'function'
      ? window.buildFormattedResolutionStepsHtml(rawExp, item, correctIndex, correctLetter, isCE, related)
      : `<div class="stepResolutionBlock right"><b>✅ Passo a passo do raciocínio</b><p>${escText(rawExp)}</p></div>`;

    const optionsBreakdown=(item.options||[]).map((opt,idx)=>{
      const letter=String.fromCharCode(65+idx);
      const isRight=idx===correctIndex;
      const isUserPick=idx===chosenIndex;
      const statusTag=isRight?'<span class="stepOptBadge good">✓ Correta</span>':isUserPick?'<span class="stepOptBadge bad">✗ Sua escolha</span>':'<span class="stepOptBadge neutral">Distrator</span>';
      return `<div class="stepOptionItem ${isRight?'isRight':isUserPick?'isWrong':''}"><div><b>${letter})</b> ${escText(opt)}</div>${statusTag}</div>`;
    }).join('');

    const interactiveControls=interactive?`
      <div class="resolutionActionBar">
        <button type="button" class="ghost small" id="spawnTwinQuestionBtn">⚡ Gerar questão gêmea</button>
        <button type="button" class="ghost small" id="explainEasyAnalogyBtn">🧠 Explicar fácil (analogia)</button>
        <button type="button" class="ghost small" id="createConceptFlashcardBtn">🃏 Criar flashcard do conceito</button>
        <button type="button" class="ghost small" id="toggleFavoriteQuestionBtn">${isFav?'⭐ Favorita (salva)':'☆ Favoritar questão'}</button>
        <button type="button" class="ghost small" id="saveQuestionNoteBtn">📌 Salvar no Caderno</button>
        <button type="button" class="ghost small" id="askQapInstructorBtn">🦅 QAP Instrutor IA</button>
        <button type="button" class="ghost small" id="reportQuestionIssueBtn">🚩 Corrigir / Reportar</button>
      </div>
      <div id="easyAnalogyOutput" hidden class="stepResolutionBlock concept" style="margin-top:6px"></div>
      <div class="personalQuestionBizuBox">
        <label class="small muted" for="personalQuestionCommentInput">💬 Meu bizu / anotação nesta questão (estilo TEC/Qconcursos/Caveira):</label>
        <div class="personalBizuRow">
          <input type="text" id="personalQuestionCommentInput" value="${escText(savedComment)}" placeholder="Escreva seu mnemônico ou observação rápida para lembrar desta questão...">
          <button type="button" class="ghost small" id="savePersonalQuestionCommentBtn">Salvar bizu</button>
        </div>
      </div>` : '';

    const chosenText=(Number.isInteger(chosenIndex)&&chosenIndex>=0&&item.options?.[chosenIndex])?item.options[chosenIndex]:'';
    const correctText=item.options?.[correctIndex]||'';
    const optRangeLabel=isCE?'CERTO / ERRADO':`A–${String.fromCharCode(64+Math.max(4,optsList.length))}`;
    const directComparisonHtml=(!ok&&chosenText)?`
      <div class="directChoiceComparison">
        <div class="choiceCompareCard wrongPick">
          <span class="choiceCompareLabel">✗ SUA ESCOLHA (${isCE?chosenLetter:`ALTERNATIVA ${chosenLetter}`})</span>
          <p>${escText(chosenText)}</p>
        </div>
        <div class="choiceCompareCard rightPick">
          <span class="choiceCompareLabel">✓ ${escText(keyDetails.label.toUpperCase())} (${isCE?correctLetter:`ALTERNATIVA ${correctLetter}`})</span>
          <p>${escText(correctText)}</p>
        </div>
      </div>
    `:(!ok&&chosenIndex===-2)?`
      <div class="directChoiceComparison">
        <div class="choiceCompareCard wrongPick" style="border-color:#94a3b8;background:rgba(30,41,59,.65)">
          <span class="choiceCompareLabel" style="color:#cbd5e1">⚪ DEIXADA EM BRANCO (ESTRATÉGIA LÍQUIDA CAVEIRA · 0 PT)</span>
          <p>Você optou por não chutar esta questão para proteger sua pontuação líquida.</p>
        </div>
        <div class="choiceCompareCard rightPick">
          <span class="choiceCompareLabel">✓ ${escText(keyDetails.label.toUpperCase())} (${isCE?correctLetter:`ALTERNATIVA ${correctLetter}`})</span>
          <p>${escText(correctText)}</p>
        </div>
      </div>
    `:'';

    return `<div class="boaRespostaResolution ${ok?'isGood':'isBad'}">
      <div class="resolutionHeader">
        <div>
          <span class="eyebrow">${ok?'✓ RESPOSTA CORRETA · +25 XP':chosenIndex===-2?'⚪ QUESTÃO EM BRANCO · CONFIRA A RESOLUÇÃO':'✗ RESPOSTA INCORRETA · APRENDA COM O PASSO A PASSO'}</span>
          <h4>Gabarito: ${isCE?correctLetter:`Alternativa ${correctLetter}`}${!ok?` (${chosenIndex===-2?'deixada em branco':chosenIndex===-1?'tempo esgotado':`você marcou ${chosenLetter}`})`:''}</h4>
        </div>
        <span class="tag">${escText(item.board||(normalizedOrigin(item)==='oficial'?'Prova Oficial':'Estilo Banca'))}</span>
      </div>
      <p class="small muted">${escText(keyDetails.label)}${keyDetails.source?` · Fonte informada: ${escText(keyDetails.source)}`:''}. Explicações de IA são apoio ao estudo e devem ser conferidas.</p>
      ${directComparisonHtml}
      ${!ok?(`<div class="stepResolutionBlock wrongAnalysis" style="border-left:4px solid #f43f5e;background:rgba(136,19,55,.22);margin-bottom:8px"><b>🔍 Roteiro de revisão da sua resposta (pistas automáticas)</b><p style="margin-top:4px;line-height:1.5">${buildSpecificErrorDiagnosis(item,chosenIndex,correctIndex,isCE)}</p></div>`):''}
      ${stepsHtml}
      <details class="resolutionOptionsDetails" ${!ok?'open':''}>
        <summary>Ver conferência alternativa por alternativa (${optRangeLabel})</summary>
        <div class="stepOptionsList">${optionsBreakdown}</div>
      </details>
      ${interactiveControls}
    </div>`;
  }

  async function saveQuestionsToCampaign(title,subject,questions,sourceLabel='Banco de Questões'){
    if(!Array.isArray(questions)||!questions.length)return 0;
    const validQuestion=item=>item?.statement&&Array.isArray(item?.options)&&item.options.length>=2&&item.options.length<=5&&item.options.every(option=>String(option??'').trim());
    const hasRawKey=item=>item.correct_index!==null&&item.correct_index!==undefined&&String(item.correct_index).trim()!==''&&typeof item.correct_index!=='boolean'&&typeof item.correct_index!=='object'&&Number.isInteger(Number(item.correct_index))&&Number(item.correct_index)>=0&&Number(item.correct_index)<item.options.length;
    const normalized=questions.filter(validQuestion).map(item=>({
      ...item,
      _fp:undefined,
      subject:resolveStrictQuestionDiscipline(item.statement,item.topic,item.subject||subject||'Conteúdo Geral',item.options),
      topic:String(item.topic||title||'Geral').trim(),
      board:String(item.board||sourceLabel).trim(),
      statement:String(item.statement).trim(),
      options:item.options.map(o=>String(o).trim()),
      correct_index:hasRawKey(item)?Number(item.correct_index):-1,
      answer_unknown:Boolean(item.answer_unknown||!hasRawKey(item)),
      explanation:String(item.explanation||'').trim(),
      difficulty:['facil','medio','dificil'].includes(normalizedDifficulty(item))?normalizedDifficulty(item):'medio',
      origin:item.origin==='adaptada_do_pdf'?'adaptada_do_pdf':normalizedOrigin(item)==='oficial'?'oficial':'autoral'
    }));
    if(!normalized.length)return 0;

    const existingFp=new Set((ALL_QUESTIONS||[]).map(item=>questionFingerprint(item)));
    const fresh=normalized.filter(item=>!existingFp.has(questionFingerprint(item)));
    const toAdd=fresh.length?fresh:normalized;

    state.customQuestionsByCampaign=state.customQuestionsByCampaign||{};
    const campId=state.activeCampaignId;
    const currentLocal=state.customQuestionsByCampaign[campId]||[];
    const localFp=new Set(currentLocal.map(item=>questionFingerprint(item)));
    for(const item of toAdd){
      if(!localFp.has(questionFingerprint(item)))currentLocal.push(item);
      if(!existingFp.has(questionFingerprint(item)))ALL_QUESTIONS.push(item);
    }
    state.customQuestionsByCampaign[campId]=currentLocal.slice(-400);
    LEARNING_SUBJECTS=typeof window.computeValidLearningSubjects==='function'?window.computeValidLearningSubjects():[...new Set([...LEARNING_SUBJECTS,...toAdd.map(x=>x.subject)])].sort((a,b)=>a.localeCompare(b,'pt-BR'));
    save();

    const campaign=typeof activeCampaign==='function'?activeCampaign():null;
    if(cloudSession&&campaign?.dbId){
      try{
        await cloudFetch('generated_study_content',{
          method:'POST',
          headers:{'Content-Type':'application/json',Prefer:'return=representation'},
          body:JSON.stringify([{
            campaign_id:campaign.dbId,
            user_id:cloudSession.user.id,
            content_type:'summary',
            title:String(title||`Caderno ${sourceLabel}`).slice(0,140),
            content:{
              is_question_pack:true,
              subject:toAdd[0].subject,
              source:sourceLabel,
              explanation:`Pacote de questões (${sourceLabel}) salvo no banco da campanha.`,
              points:[],
              flashcards:[],
              questions:toAdd
            },
            source_refs:[{title:sourceLabel}]
          }])
        });
        if(sourceLabel!=='Banco Oficial Compartilhado'){
          const sharedRows=toAdd.filter(qItem=>!qItem.answer_unknown&&Number.isInteger(Number(qItem.correct_index))&&Number(qItem.correct_index)>=0&&Number(qItem.correct_index)<=4).map(qItem=>({
            fingerprint:questionFingerprint(qItem),
            subject:canonicalSubjectName(qItem.subject||subject||'Conteúdo Geral'),
            topic:String(qItem.topic||title||'Geral').trim().slice(0,160),
            board:String(qItem.board||sourceLabel||'Banca Oficial').trim().slice(0,80),
            difficulty:['facil','medio','dificil'].includes(qItem.difficulty)?qItem.difficulty:'medio',
            origin:['oficial','adaptada_do_pdf','autoral'].includes(qItem.origin)?qItem.origin:'oficial',
            statement:String(qItem.statement).trim(),
            options:qItem.options,
            correct_index:Number(qItem.correct_index),
            explanation:answerKeyExportExplanation(qItem),
            created_by:cloudSession.user.id
          }));
          if(sharedRows.length){
            await cloudFetch('shared_question_bank?on_conflict=fingerprint',{
              method:'POST',
              headers:{'Content-Type':'application/json',Prefer:'resolution=merge-duplicates,return=minimal'},
              body:JSON.stringify(sharedRows.slice(0,200))
            }).catch(()=>{});
          }
        }
      }catch(e){
        console.warn('Salvamento em nuvem pendente; mantido localmente',e);
      }
    }

    renderQuestionFilters();
    populateTopicFilter();
    updateQuestionPool();
    renderExamBankHub();
    return toAdd.length;
  }

  function buildLocalCognitiveTwinQuestion(mold){
    const subj=learningCategory(mold?.subject||'Conteúdo Geral');
    const topic=String(mold?.topic||'Fixação de Conceito').replace(/^\[Gêmea\]\s*/i,'').trim();
    const board=mold?.board||'Estilo Banca';
    const origOpts=Array.isArray(mold?.options)?mold.options:[];
    const origCorrectIdx=Math.min(Math.max(0,Number(mold?.correct_index)||0),Math.max(0,origOpts.length-1));
    const correctText=String(origOpts[origCorrectIdx]||'Aplicação correta da regra prevista no edital.').trim();
    const attempt=mold?._lastAttempt||null;
    const wrongDistractors=origOpts.filter((_,i)=>i!==origCorrectIdx).map(x=>String(x).trim()).filter(Boolean);
    const optionCount=Math.min(5,Math.max(2,origOpts.length||4));
    const fillers=['Previsão incompatível com o texto normativo e entendimento dominante.','Regra diversa da prevista na norma, apoiada em exceção que não existe.','Interpretação restritiva não admitida pela doutrina e pela jurisprudência.','Aplicação automática da regra, sem observar os requisitos legais.'];
    let fillerIndex=0;
    while(wrongDistractors.length<optionCount-1)wrongDistractors.push(fillers[fillerIndex++%fillers.length]);
    const cleanExp=String(mold?.explanation||'').replace(/\s+/g,' ').trim();
    const angleNote=attempt&&!attempt.ok&&attempt.chosenText
      ?`Atenção: na questão anterior você marcou "${shortLabel(attempt.chosenText,65)}". Compare os elementos do caso e identifique a alternativa que aplica a regra exata:`
      :`Em uma variação de prova da banca ${board} sobre "${topic}", analise as assertivas e assinale a diretriz juridicamente/tecnicamente correta:`;
    const newStatement=`🧬 [Questão Gêmea de Fixação · ${topic}] ${angleNote}`;
    let newOptions,newCorrectIndex;
    if(optionCount===2&&origOpts.length===2){newOptions=origOpts.map(x=>String(x).trim());newCorrectIndex=origCorrectIdx}
    else{
      const pool=[{text:correctText,ok:true},...wrongDistractors.slice(0,optionCount-1).map(text=>({text,ok:false}))];
      for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}
      newOptions=pool.map(x=>x.text);newCorrectIndex=pool.findIndex(x=>x.ok);
    }
    const newExplanation=[
      `Conceito-chave: Fixação ativa do tema "${topic}" (${subj}).`,
      `✅ Alternativa correta: ${correctText}`,
      attempt&&!attempt.ok&&attempt.chosenText
        ?`❌ Análise do distrator que confundiu antes: A opção "${attempt.chosenText}" é incorreta e atua como pegadinha recorrente.`
        :`❌ Análise das alternativas: As demais opções invertem prazos, requisitos ou generalizam exceções sobre ${topic}.`,
      `⚠️ Pegadinha da banca (${board}): ${cleanExp?shortLabel(cleanExp,180):'Leia atentamente os termos restritivos ou exceções antes de marcar.'}`
    ].join('\n');
    return{
      subject:subj,
      topic:`[Gêmea] ${topic}`,
      board,
      difficulty:normalizedDifficulty(mold),
      origin:'autoral',
      statement:newStatement,
      options:newOptions,
      correct_index:newCorrectIndex,
      explanation:newExplanation
    };
  }
  window.buildLocalCognitiveTwinQuestion=buildLocalCognitiveTwinQuestion;

  function reportOrFixCurrentQuestion(item,btnEl){
    if(!item)return;
    const currentLetter=Number.isInteger(Number(item.correct_index))&&Number(item.correct_index)>=0?String.fromCharCode(65+Number(item.correct_index)):'pendente';
    const ans=prompt(`Auditoria Pedagógica da Questão (" ${shortLabel(item.statement,60)} "):

• Digite uma letra existente para validar pessoalmente o gabarito (atual: ${currentLetter});
• Ou escreva uma observação para reportar erro no enunciado/comentário.
Uma validação pessoal não transforma a resposta em gabarito oficial.`, '');
    if(ans===null)return;
    const clean=ans.trim();
    if(/^[A-Ea-e]$/.test(clean)){
      const newIdx=clean.toUpperCase().charCodeAt(0)-65;
      if(!Array.isArray(item.options)||newIdx>=item.options.length)return toast('Essa alternativa não existe nesta questão. Nenhuma alteração foi salva.');
      const reference=prompt('Informe a fonte ou justificativa da sua validação (opcional):','');
      if(reference===null)return;
      const fp=questionFingerprint(item);
      applyReviewedAnswerKey(item,newIdx,reference);
      for(const qItem of (ALL_QUESTIONS||[])){
        if(qItem!==item&&questionFingerprint(qItem)===fp&&answerOptionsSignature(qItem)===answerOptionsSignature(item)){
          const sourceIndex=qItem.options.findIndex(opt=>answerOptionText(opt)===answerOptionText(item.options[newIdx]));
          if(sourceIndex>=0)applyReviewedAnswerKey(qItem,sourceIndex,reference);
        }
      }
      save();
      window.persistToLocalDatabase?.(state?.activeCampaignId);
      if(btnEl)btnEl.textContent=`✓ Gabarito ajustado p/ ${clean.toUpperCase()}`;
      toast(`Gabarito validado por você: ${clean.toUpperCase()}. Histórico e referência preservados.`);
      return;
    }
    if(clean.length>=3){
      state.reportedQuestions=state.reportedQuestions||{};
      state.reportedQuestions[questionFingerprint(item)]={note:clean,statement:item.statement,subject:item.subject,at:new Date().toISOString()};
      save();
      if(btnEl)btnEl.textContent='🚩 Reportada';
      toast('Observação registrada! A questão foi marcada para revisão.');
    }
  }
  window.reportOrFixCurrentQuestion=reportOrFixCurrentQuestion;

  async function spawnTwinQuestionForCurrent(currentItem,btnEl){
    if(btnEl){btnEl.disabled=true;btnEl.textContent='⏳ Gerando questão gêmea...'}
    const attempt=currentItem?._lastAttempt||null;
    const errorContext=attempt
      ?(attempt.ok
          ?`O aluno ACERTOU a questão-molde marcando "${attempt.correctText}". Gere uma questão gêmea um nível mais profunda cobrando um caso prático ou exceção legal do mesmo tópico.`
          :`O aluno ERROU a questão-molde: marcou o distrator "${attempt.chosenText}" em vez da correta "${attempt.correctText}". Gere uma questão gêmea inédita que trabalhe exatamente a diferença entre esse distrator e a regra verdadeira.`)
      :'Gere uma questão gêmea cobrando o mesmo tema sob novo caso prático.';
    try{
      let twin=null;
      if(cloudSession&&navigator.onLine){
        const session=await validSession().catch(()=>null);
        if(session){
          const res=await fetch(`${SUPABASE_URL}/functions/v1/assistente-pmpe`,{
            method:'POST',
            headers:{...authHeaders(session.access_token)},
            body:JSON.stringify({
              action:'generate_structured_questions',
              submode:'twin',
              count:1,
              subject:learningCategory(currentItem.subject),
              topic:currentItem.topic||'Assunto do Edital',
              board:currentItem.board||'Instituto AOCP',
              difficulty:normalizedDifficulty(currentItem),
              mold_question:currentItem,
              student_error_context:errorContext,
              campaign_id:activeCampaign()?.dbId
            })
          }).catch(()=>null);
          if(res?.ok){
            const data=await res.json().catch(()=>({}));
            if(data?.questions?.[0])twin=data.questions[0];
          }
        }
      }
      if(!twin){
        twin=buildLocalCognitiveTwinQuestion(currentItem);
      }
      await saveQuestionsToCampaign(`Questão Gêmea · ${twin.topic}`,twin.subject,[twin],twin.board||'Questão Gêmea IA');
      if(activeQuestions&&Array.isArray(activeQuestions.questions)){
        activeQuestions.questions.splice(activeQuestions.current+1,0,prepareQuestion(twin));
        q('#questionCounter').textContent=`${activeQuestions.current+1}/${activeQuestions.questions.length} · ${normalizedDifficulty(currentItem).toUpperCase()}`;
        q('#nextQuestion').textContent='Responder questão gêmea →';
      }
      if(btnEl)btnEl.textContent='✓ Questão gêmea na fila!';
      toast(attempt&&!attempt.ok?'🧬 Questão gêmea focada no seu erro criada e colocada como próxima!':'🧬 Questão gêmea de fixação criada e colocada como próxima da fila!');
    }catch(error){
      if(btnEl){btnEl.disabled=false;btnEl.textContent='⚡ Gerar questão gêmea'}
      toast(error.message);
    }
  }

  async function explainQuestionWithEasyAnalogy(item,btnEl){
    const outBox=q('#easyAnalogyOutput');
    if(!outBox)return;
    if(!cloudSession)return toast('Entre na sua conta para usar a explicação com analogia.');
    if(btnEl){btnEl.disabled=true;btnEl.textContent='⏳ Gerando analogia...'}
    try{
      const session=await validSession();
      if(!session)throw new Error('Sessão expirada.');
      const correctOpt=item.options?.[Number(item.correct_index)||0]||'';
      const prompt=`Explique de forma extremamente simples, direta e com uma analogia prática do dia a dia policial por que a resposta correta para a questão abaixo é "${correctOpt}". Máximo de 2 parágrafos curtos.\n\nQuestão: ${item.statement}`;
      const res=await fetch(`${SUPABASE_URL}/functions/v1/assistente-pmpe`,{
        method:'POST',
        headers:{...authHeaders(session.access_token)},
        body:JSON.stringify({question:prompt,context:item.explanation||'',mode:'explicar',campaign_id:activeCampaign()?.dbId})
      });
      const data=await res.json().catch(()=>({}));
      if(!res.ok)throw new Error(data.error||'Não foi possível gerar a analogia.');
      outBox.hidden=false;
      outBox.innerHTML=`<b>🧠 Explicação descomplicada com analogia</b><p>${escText(data.answer||'')}</p>`;
      if(btnEl)btnEl.textContent='✓ Analogia exibida';
    }catch(err){
      if(btnEl){btnEl.disabled=false;btnEl.textContent='🧠 Explicar fácil (analogia)'}
      toast(err.message);
    }
  }

  function createFlashcardFromQuestion(item,btnEl){
    if(!item)return false;
    if(btnEl)btnEl.disabled=true;
    const subject=resolveStrictQuestionDiscipline(item)||learningCategory(item.subject)||'Geral';
    const topic=String(item.topic||subject).trim();
    const explanation=String(item.explanation||'').trim();
    const correctIdx=Number(item.correct_index);
    const correctText=String(item.options?.[correctIdx]||'').trim();

    let concept='';
    const conceptMatch=explanation.match(/conceito[- ]chave\s*[:：]?\s*([^\n.]+(?:\.[^\n]*)?)/i);
    if(conceptMatch){
      concept=conceptMatch[1].trim();
    }
    if(!concept&&explanation){
      const clean=explanation
        .split(/❌|✅|⚠️|Alternativa correta|An[aá]lise das/i)[0]
        .replace(/^conceito[- ]chave\s*[:：]?\s*/i,'')
        .trim();
      concept=clean.split(/(?<=\.)\s+/).slice(0,2).join(' ').slice(0,220);
    }
    if(!concept||concept.length<25){
      if(correctText.length>=25){
        concept=`Regra aplicável sobre ${topic}: ${correctText}`;
      }else{
        if(btnEl){btnEl.disabled=false;toast('Esta questão não tem explicação suficiente para gerar um flashcard conceitual.');}
        return false;
      }
    }

    const front=topic
      ?`O que você precisa lembrar sobre: ${topic}?`
      :`Conceito essencial – ${subject}`;
    const backParts=[concept];
    if(correctText&&!concept.includes(correctText)){
      backParts.push(`\n\nRegra-modelo: ${correctText}`);
    }
    const back=backParts.join('');

    if(typeof window.isValidFlashcardItem==='function'&&!window.isValidFlashcardItem(front,back)){
      if(btnEl){btnEl.disabled=false;toast('Flashcard gerado não passou na validação pedagógica.');}
      return false;
    }

    const key=typeof fcKey==='function'?fcKey([subject,front,back]):`${subject}|${front}`.toLowerCase();
    const already=(ALL_FLASHCARDS||[]).some(c=>{
      const k=typeof fcKey==='function'?fcKey(c):`${c[0]}|${c[1]}`.toLowerCase();
      return k===key||String(c[1]||'').toLowerCase()===front.toLowerCase();
    });
    if(already){
      if(btnEl){btnEl.disabled=false;btnEl.textContent='✓ Já na fila';toast('Já existe um flashcard deste conceito na sua fila.');}
      return false;
    }

    ALL_FLASHCARDS=ALL_FLASHCARDS||[];
    ALL_FLASHCARDS.unshift([subject,front,back]);
    state.userNotes=Array.isArray(state.userNotes)?state.userNotes:[];
    state.userNotes.unshift({
      id:`fc-concept-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,
      title:front,
      content:back,
      subject,
      campaignId:state.activeCampaignId,
      updated:new Date().toISOString()
    });
    if(typeof save==='function')save();
    if(typeof updateFlashcardSpacedStats==='function')updateFlashcardSpacedStats();
    if(typeof renderCard==='function')renderCard();
    if(btnEl){
      btnEl.disabled=false;
      btnEl.textContent='✓ Conceito salvo nos Flashcards';
      toast('🃏 Flashcard criado a partir do conceito da questão e adicionado à fila de revisão!');
    }
    return true;
  }
  window.createFlashcardFromQuestion=createFlashcardFromQuestion;

  function generateFlashcardsFromNativeBank(limit=30){
    const bank=(typeof NATIVE_POLICE_QUESTION_BANK!=='undefined'?NATIVE_POLICE_QUESTION_BANK:ALL_QUESTIONS||[]).filter(qItem=>
      (qItem.origin==='autoral'||qItem.origin==='nativo')&&String(qItem.explanation||'').length>80
    );
    let created=0;
    for(const qItem of bank){
      if(created>=limit)break;
      if(createFlashcardFromQuestion(qItem,null))created++;
    }
    toast(`🃏 ${created} flashcards conceituais gerados a partir do banco nativo.`);
    return created;
  }
  window.generateFlashcardsFromNativeBank=generateFlashcardsFromNativeBank;

  function saveCurrentQuestionToNotes(item){
    const correctIdx=Number(item.correct_index)||0;
    const correctLetter=String.fromCharCode(65+correctIdx);
    const noteTitle=`Questão comentada: ${item.topic||item.subject||'Estudo'}`;
    const noteBody=[
      `Disciplina: ${learningCategory(item.subject)}`,
      `Enunciado: ${item.statement}`,
      `Alternativa correta: ${correctLetter}) ${item.options?.[correctIdx]||''}`,
      `Resolução: ${item.explanation||''}`
    ].join('\n\n');
    state.userNotes=state.userNotes||[];
    state.userNotes.push({
      id:String(Date.now()),
      title:noteTitle,
      content:noteBody,
      subject:learningCategory(item.subject)||'Geral',
      campaignId:state.activeCampaignId,
      updated:new Date().toISOString()
    });
    save();
    if(typeof renderNotes==='function')renderNotes();
    toast('Questão e resolução passo a passo salvas nas suas Anotações!');
  }

  // Sobrescreve showQuestion e answerQuestion com Caixa de Pergunta Moderna (Estilo Qconcursos / TEC / boaResposta + Solo Leveling)
  window.showQuestion=function(){
    const battle=activeQuestions;
    if(!battle)return;
    const item=battle.questions[battle.current];
    item._answerStartedAt=Date.now();
    const diff=normalizedDifficulty(item);
    const diffLabel={facil:'🟢 Fácil',medio:'🟡 Média',dificil:'🔴 Difícil'}[diff]||'🟡 Média'; const sealOrigin = typeof window.questionOriginSeal === 'function' ? window.questionOriginSeal(item) : 'OFICIAL';
    const boardLabel=item.board||(normalizedOrigin(item)==='oficial'?'Prova Oficial':'Autoral IA');
    const subjName=learningCategory(item.subject)||'Disciplina';
    const topicName=shortLabel(item.topic||'Geral',42);
    const pct=Math.round(((battle.current+1)/Math.max(1,battle.questions.length))*100);
    if(q('#questionProgressFill'))q('#questionProgressFill').style.width=`${pct}%`;
    if(q('#questionMetaPills')){
      q('#questionMetaPills').innerHTML=`
        <span class="qMetaPill board">🎯 ${escText(boardLabel)}</span><span class="qMetaPill seal" style="font-weight:bold;background:rgba(56,189,248,0.18);border:1px solid rgba(56,189,248,0.4);">🏷️ ${escText(sealOrigin)}</span>
        <span class="qMetaPill">${subjectIconForName(subjName)} ${escText(subjName)}</span>
        <span class="qMetaPill">📌 ${escText(topicName)}</span>
        <span class="qMetaPill ${diff}">${diffLabel}</span>
      `;
    }
    q('#questionCounter').textContent=`Questão ${battle.current+1} de ${battle.questions.length}`;
    const normaMetaEl=q('#questionNormaBaseMeta');
    if(normaMetaEl){
      const nb=item.norma_base||(typeof inferLegalNormaBase==='function'?inferLegalNormaBase(item):'Bibliografia Oficial');
      const verified=Boolean(item.verified_by&&item.verified_at);
      normaMetaEl.textContent=`⚖️ Referência sugerida: ${nb} · ${verified?`Conferência informada: ${item.verified_at}`:'Conferência documental pendente'}`;
    }
    const figUrl=item.figure_data_url||item.image_url||(state?.questionFigures?.[typeof questionFingerprint==='function'?questionFingerprint(item):'']||'');
    const stmtForVis=String(item.statement||'').replace(/\b(?:quadro[\s-]negro|quadro\s+de\s+\w+|quadro\s+cl[íi]nico|quadro\s+funcional|tabela[\s-]verdade|diagramas?\s+l[óo]gicos?|mapa\s+do\s+edital|mapa\s+mental)\b/gi,' ');const needsVisualCue=/\b(?:(?:observe|analise|veja|conforme|segundo|de\s+acordo\s+com|na|no|da|do|pela|pelo)\s+(?:a\s+|o\s+)?(?:figura|imagem|gr[áa]fico|tabela|planilha|charge|tirinha)|(?:figura|imagem|gr[áa]fico|tabela|quadro|diagrama)\s+(?:abaixo|a\s+seguir|\d+)|charge\s+(?:abaixo|a\s+seguir)|tirinha\s+(?:abaixo|a\s+seguir))\b/i.test(stmtForVis);
    const figHtml=figUrl
      ?`<div class="questionFigureBox" style="margin:10px 0;padding:10px;border-radius:12px;background:#071320;border:1px solid rgba(56,189,248,0.35);text-align:center;"><img src="${figUrl}" alt="Figura da questão" style="max-width:100%;max-height:280px;border-radius:8px;margin:0 auto;display:block;"><div class="small muted" style="margin-top:6px;">🖼️ Figura/Tabela extraída do documento original</div></div>`
      :(needsVisualCue?`<div class="questionFigureBox" style="margin:8px 0;padding:8px 12px;border-radius:10px;background:rgba(14,34,56,0.65);border:1px dashed rgba(56,189,248,0.4);display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;"><span class="small muted">🖼️ Esta questão menciona uma figura, tabela ou gráfico:</span><label class="ghost small" style="width:auto;padding:4px 10px;font-size:11px;cursor:pointer;margin:0;">📎 Anexar Figura da Questão<input type="file" accept="image/*" id="attachQuestionFigureInput" hidden></label></div>`:'');
    q('#questionText').innerHTML=formatStatementWithHighlights(item.statement,item)+figHtml;
    const figInput=q('#attachQuestionFigureInput');
    if(figInput){
      figInput.onchange=e=>{
        const f=e.target.files?.[0];
        if(!f)return;
        const reader=new FileReader();
        reader.onload=()=>{
          item.figure_data_url=String(reader.result||'');
          if(typeof state==='object'&&state&&typeof questionFingerprint==='function'){
            state.questionFigures=state.questionFigures||{};
            state.questionFigures[questionFingerprint(item)]=item.figure_data_url;
            if(typeof save==='function')save();
          }
          window.showQuestion();
          toast('🖼️ Figura anexada à questão com sucesso!');
        };
        reader.readAsDataURL(f);
      };
    }
    q('#questionOptions').innerHTML=(item.options||[]).map((o,i)=>`<div class="optionWithScissors"><button type="button" class="optionMainBtn" data-question-index="${i}"><span class="optLetterBadge">${String.fromCharCode(65+i)}</span><span class="optBodyText">${escText(o)}</span></button><button type="button" class="scissorBtn" data-scissor-index="${i}" title="Riscar/eliminar alternativa (estilo TEC/Qconcursos)" aria-label="Riscar alternativa ${String.fromCharCode(65+i)}">✂</button></div>`).join('')+`<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;margin-top:4px"><button type="button" class="ghost small" id="skipQuestionBlankBtn" style="width:auto;padding:6px 12px;font-size:.77rem" title="Pular sem marcar alternativa (Estratégia Líquida Cebraspe/Caveira: não perde ponto líquido)">⚪ Deixar em Branco (Modo Líquido Caveira)</button><button type="button" class="ghost small" id="toggleModalPaperModeBtn" style="width:auto;padding:6px 10px;font-size:.75rem">☀️ Modo Papel</button></div>`;
    q('#questionFeedback').innerHTML='';
    q('#nextQuestion').hidden=true;
    battle.answered=false;
    if(q('#closeQuestionsTopBtn')){
      q('#closeQuestionsTopBtn').onclick=()=>{
        if(typeof window.requestExitQuestionSession==='function')return window.requestExitQuestionSession();
        activeQuestions=null;q('#questionDialog')?.close();
      };
    }
    if(q('#closeQuestions')){
      q('#closeQuestions').onclick=()=>{
        if(typeof window.requestExitQuestionSession==='function')return window.requestExitQuestionSession();
        activeQuestions=null;q('#questionDialog')?.close();
      };
    }
    if(typeof window.syncQuestionPrevAndRestoreState==='function'){
      window.syncQuestionPrevAndRestoreState(battle, item);
    }
    qa('[data-question-index]').forEach(b=>b.onclick=()=>window.answerQuestion(b,item));
    if(q('#skipQuestionBlankBtn'))q('#skipQuestionBlankBtn').onclick=()=>window.skipQuestionBlank(item);
    if(q('#toggleModalPaperModeBtn'))q('#toggleModalPaperModeBtn').onclick=()=>togglePaperReadingMode();
    qa('[data-scissor-index]').forEach(sBtn=>sBtn.onclick=e=>{
      e.stopPropagation();
      if(battle.answered)return;
      const idx=sBtn.dataset.scissorIndex;
      const optBtn=q(`[data-question-index="${idx}"]`);
      if(optBtn){
        optBtn.classList.toggle('eliminatedOption');
        sBtn.classList.toggle('active');
      }
    });
  };

  window.answerQuestion=function(button,item){
    const battle=activeQuestions;
    if(!battle||battle.answered)return;
    const grading=gradeAnswer(item,button?.dataset?.questionIndex);
    if(!grading.scored){
      battle.answered=true;
      q('#questionFeedback').innerHTML=formatStepByStepResolution(item,Number(button?.dataset?.questionIndex),false,true);
      qa('[data-question-index],[data-scissor-index]').forEach(b=>b.disabled=true);
      const reportBtn=q('#reportQuestionIssueBtn');
      if(reportBtn)reportBtn.onclick=()=>reportOrFixCurrentQuestion(item,reportBtn);
      q('#nextQuestion').hidden=false;
      q('#nextQuestion').textContent='Próxima questão →';
      return;
    }
    battle.answered=true;
    const chosen=Number(button.dataset.questionIndex),correct=Number(item.correct_index),ok=chosen===correct;
    const fp=questionFingerprint(item);
    state.answeredQuestionFingerprints=state.answeredQuestionFingerprints||{};
    state.answeredQuestionFingerprints[fp]=ok?'correct':'wrong';
    recordQuestionResult(item,ok,chosen);
    if(ok){
      battle.correct++;
      battle.streak=(battle.streak||0)+1;
      button.classList.add('correct');
      applyXpLocal(25,'acerto_questao');
      recordQuestionAttemptServer(
        item.subject||battle.subject,
        item.topic||'geral',
        true,
        battle.mode||'practice'
      ).then(serverRes=>{
        if(serverRes?.mastery_bonus>0){
          applyXpLocal(serverRes.mastery_bonus,'bonus_maestria');
          toast(`🎯 Bônus de domínio +${serverRes.mastery_bonus} XP (maestria ${Math.round(serverRes.mastery||0)}% no tópico)!`);
        }
      });
    }else{
      battle.streak=0;
      button.classList.add('wrong');
      qa('[data-question-index]').find(b=>Number(b.dataset.questionIndex)===correct)?.classList.add('correct');
      recordQuestionAttemptServer(
        item.subject||battle.subject,
        item.topic||'geral',
        false,
        battle.mode||'practice'
      );
    }
    const optStats=computeQuestionOptionChoiceStats(item,chosen);
    qa('[data-question-index]').forEach(btn=>{
      const idx=Number(btn.dataset.questionIndex);
      const pct=optStats.pcts[idx]??0;
      const isCorr=idx===correct;
      const isTrap=!isCorr&&idx===optStats.trapIndex&&pct>=12;
      const oldBadge=btn.querySelector('.optStatPill');
      if(oldBadge)oldBadge.remove();
      const pillCls=isCorr?'isCorrectStat':isTrap?'isTrapStat':'isNeutralStat';
      const pillTxt=isCorr?`📊 ${pct}% ✓`:isTrap?`⚠️ ${pct}% (Seu erro mais frequente)`:`📊 ${pct}%`;
      btn.insertAdjacentHTML('beforeend',`<span class="optStatPill ${pillCls}">${pillTxt}</span>`);
    });
    const trapLetter=optStats.trapIndex>=0?String.fromCharCode(65+optStats.trapIndex):'-';
    const statSummaryHtml=`<div class="communityOptionStatsBar" style="margin-bottom:10px;padding:9px 12px;border-radius:10px;background:rgba(8,22,38,0.9);border:1px solid rgba(56,189,248,0.28);font-size:12px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;"><span>📊 <b>Seu histórico nesta questão (${optStats.totalSamples} resposta${optStats.totalSamples===1?"":"s"} registrada${optStats.totalSamples===1?"":"s"}):</b> <strong style="color:#34d399;">${optStats.pcts[correct]}% no gabarito (${String.fromCharCode(65+correct)})</strong></span>${optStats.trapIndex>=0?`<span style="color:#fbbf24;">⚠️ Seu erro mais frequente: <b>Alternativa ${trapLetter} (${optStats.pcts[optStats.trapIndex]}%)</b></span>`:''}${optStats.legacySamples?'<span class="small muted">Registros antigos sem vínculo seguro de alternativa/portal não entram nos percentuais.</span>':''}</div>`;
    q('#questionFeedback').innerHTML=statSummaryHtml+formatStepByStepResolution(item,chosen,ok,true);
    qa('[data-question-index],[data-scissor-index]').forEach(b=>b.disabled=true);

    item._lastAttempt={ok,chosenIndex:chosen,chosenText:item.options?.[chosen]||'',correctIndex:correct,correctText:item.options?.[correct]||''};
    const twinBtn=q('#spawnTwinQuestionBtn');
    if(twinBtn)twinBtn.onclick=()=>spawnTwinQuestionForCurrent(item,twinBtn);
    const reportBtn=q('#reportQuestionIssueBtn');
    if(reportBtn)reportBtn.onclick=()=>reportOrFixCurrentQuestion(item,reportBtn);
    const analogyBtn=q('#explainEasyAnalogyBtn');
    if(analogyBtn)analogyBtn.onclick=()=>explainQuestionWithEasyAnalogy(item,analogyBtn);
    const conceptFcBtn=q('#createConceptFlashcardBtn');
    if(conceptFcBtn)conceptFcBtn.onclick=()=>createFlashcardFromQuestion(item,conceptFcBtn);
    const flashBtn=q('#createFlashcardFromQuestionBtn');
    if(flashBtn)flashBtn.onclick=()=>createFlashcardFromQuestion(item,flashBtn);
    const favBtn=q('#toggleFavoriteQuestionBtn');
    if(favBtn)favBtn.onclick=()=>{
      state.favoriteQuestions=state.favoriteQuestions||{};
      if(state.favoriteQuestions[fp]){
        delete state.favoriteQuestions[fp];
        favBtn.textContent='☆ Favoritar questão';
        toast('Removida das favoritas.');
      }else{
        state.favoriteQuestions[fp]={savedAt:new Date().toISOString(),subject:item.subject,topic:item.topic};
        favBtn.textContent='⭐ Favorita (salva)';
        toast('Questão adicionada às suas Favoritas!');
      }
      save();
      updateQuestionPool();
    };
    const noteBtn=q('#saveQuestionNoteBtn');
    if(noteBtn)noteBtn.onclick=()=>{saveCurrentQuestionToNotes(item);noteBtn.disabled=true;noteBtn.textContent='✓ Salva no Caderno'};
    const bizuSaveBtn=q('#savePersonalQuestionCommentBtn');
    if(bizuSaveBtn)bizuSaveBtn.onclick=()=>{
      const val=q('#personalQuestionCommentInput')?.value?.trim()||'';
      state.questionPersonalNotes=state.questionPersonalNotes||{};
      if(val)state.questionPersonalNotes[fp]=val;
      else delete state.questionPersonalNotes[fp];
      save();
      toast(val?'Seu bizu pessoal foi salvo nesta questão!':'Bizu removido.');
    };

    const qapBtn=q('#askQapInstructorBtn');
    if(qapBtn)qapBtn.onclick=()=>{
      q('#questionDialog')?.close();
      openView('assistant');
      const aiInput=q('#aiQuestion');
      if(aiInput){
        aiInput.value=`[Modo QAP Policial] Explique detalhadamente os fundamentos, artigos de lei e pegadinhas de banca sobre esta questão de ${item.subject} (${item.topic}): "${item.statement}"`;
        aiInput.focus();
      }
      toast('🦅 Questão enviada para o Instrutor Tático em QAP!');
    };
    if(q('#skipQuestionBlankBtn'))q('#skipQuestionBlankBtn').disabled=true;
    q('#nextQuestion').hidden=false;
    q('#nextQuestion').textContent=battle.current===battle.questions.length-1?'Concluir batalha':'Próxima questão →';
    q('#nextQuestion').scrollIntoView({block:'nearest'});
  };

  window.skipQuestionBlank=function(item){
    const battle=activeQuestions;
    if(!battle||battle.answered)return;
    battle.answered=true;
    battle.blankCount=(battle.blankCount||0)+1;
    battle.streak=0;
    const correct=Number(item.correct_index)||0;
    qa('[data-question-index]').find(b=>Number(b.dataset.questionIndex)===correct)?.classList.add('correct');
    qa('[data-question-index],[data-scissor-index]').forEach(b=>b.disabled=true);
    if(q('#skipQuestionBlankBtn'))q('#skipQuestionBlankBtn').disabled=true;
    q('#questionFeedback').innerHTML=formatStepByStepResolution(item,-2,false,true);
    const twinBtn=q('#spawnTwinQuestionBtn');
    if(twinBtn)twinBtn.onclick=()=>spawnTwinQuestionForCurrent(item,twinBtn);
    const reportBtn=q('#reportQuestionIssueBtn');
    if(reportBtn)reportBtn.onclick=()=>reportOrFixCurrentQuestion(item,reportBtn);
    const analogyBtn=q('#explainEasyAnalogyBtn');
    if(analogyBtn)analogyBtn.onclick=()=>explainQuestionWithEasyAnalogy(item,analogyBtn);
    const noteBtn=q('#saveQuestionNoteBtn');
    if(noteBtn)noteBtn.onclick=()=>{saveCurrentQuestionToNotes(item);noteBtn.disabled=true;noteBtn.textContent='✓ Salva no Caderno'};
    q('#nextQuestion').hidden=false;
    q('#nextQuestion').textContent=battle.current===battle.questions.length-1?'Concluir batalha':'Próxima questão →';
    q('#nextQuestion').scrollIntoView({block:'nearest'});
  };

  // 2C. Diagnóstico Tático de Pontos Fortes e Pontos Fracos
  function ensureTacticalDiagnosisPanel(){
    const columns=q('#report .reportColumns');
    if(!columns||q('#tacticalDiagnosisPanel'))return;
    columns.insertAdjacentHTML('beforebegin',`<div class="card tacticalDiagnosisCard" id="tacticalDiagnosisPanel"><div class="sectionHead"><div><div class="eyebrow">DIAGNÓSTICO DE DESEMPENHO</div><h2 style="margin:3px 0 0">Pontos Fortes e Pontos Fracos</h2><p class="small muted" style="margin:3px 0 0">Identifique onde sua precisão já está segura e quais matérias precisam de reforço imediato.</p></div><span class="tag" id="diagnosisSummaryTag">Análise tática</span></div><div class="diagnosisGrid" id="diagnosisColumns"></div></div>`);
  }

  function renderTacticalDiagnosis(){
    ensureTacticalDiagnosisPanel();
    const container=q('#diagnosisColumns'),tagEl=q('#diagnosisSummaryTag');
    if(!container)return;
    const scores=(state?.scores||[]).filter(item=>!item.campaignId||item.campaignId===state.activeCampaignId);
    const missions=typeof missionPool==='function'?missionPool():[];
    const bySubject={};
    for(const item of scores){
      const name=canonicalSubjectName(item.subject||missions.find(m=>m.id===item.id)?.subject||'Conteúdo Geral', `${item.topic||''} ${item.name||''}`);
      if(isInvalidTrailSubject(name))continue;
      bySubject[name]??={total:0,correct:0,misses:0};
      bySubject[name].total+=Number(item.total||0);
      bySubject[name].correct+=Number(item.correct||0);
    }
    for(const [,err] of activeCampaignErrors()){
      const name=canonicalSubjectName(err?.subject||'Conteúdo Geral', `${err?.topic||''} ${err?.question||''}`);
      if(isInvalidTrailSubject(name))continue;
      bySubject[name]??={total:0,correct:0,misses:0};
      bySubject[name].misses+=Number(err?.misses||1);
    }

    const entries=Object.entries(bySubject).map(([name,d])=>{
      const rate=d.total>0?Math.round(d.correct/d.total*100):null;
      return {name,total:d.total,correct:d.correct,misses:d.misses,rate};
    });

    if(!entries.length){
      if(tagEl)tagEl.textContent='Sem histórico ainda';
      container.innerHTML=`<div class="empty" style="grid-column:1/-1">Resolva sua primeira bateria de questões ou simulado para destravar o mapa de Pontos Fortes e Pontos Fracos.</div>`;
      return;
    }

    const strong=entries.filter(x=>x.total>=10&&x.rate>=75).sort((a,b)=>b.rate-a.rate);
    const evolving=entries.filter(x=>x.rate!==null&&x.rate>=55&&x.rate<75).sort((a,b)=>a.rate-b.rate);
    const weak=entries.filter(x=>(x.rate===null&&x.misses>0)||(x.rate!==null&&(x.rate<55||x.misses>=2&&x.rate<75))).sort((a,b)=>(a.rate??0)-(b.rate??0));

    if(tagEl)tagEl.textContent=`${strong.length} forte(s) · ${weak.length} crítico(s)`;

    const renderItem=(item,showTrainBtn)=>`<div class="diagnosisItem"><div><b>${escText(item.name)}</b><span class="small muted">${item.total?`${item.correct}/${item.total} acertos (${item.rate}%)`:''}${item.misses?`${item.total?' · ':''}${item.misses} erro(s) ativo(s)`:''}</span></div>${showTrainBtn?`<button type="button" class="ghost small" data-train-diagnosis-subject="${escText(item.name)}">Treinar →</button>`:`<span class="tag">${item.rate}%</span>`}</div>`;

    container.innerHTML=`
      <div class="diagnosisCol strong">
        <div class="diagnosisColHead"><b>🟢 Pontos Fortes (≥75%)</b><span>${strong.length}</span></div>
        <div class="diagnosisList">${strong.length?strong.map(x=>renderItem(x,false)).join(''):'<p class="small muted">Acerte 75% ou mais em uma disciplina (mín. 10 questões) para dominá-la.</p>'}</div>
      </div>
      <div class="diagnosisCol evolving">
        <div class="diagnosisColHead"><b>🟡 Em Evolução (55–74%)</b><span>${evolving.length}</span></div>
        <div class="diagnosisList">${evolving.length?evolving.map(x=>renderItem(x,true)).join(''):'<p class="small muted">Nenhuma disciplina na faixa intermediária no momento.</p>'}</div>
      </div>
      <div class="diagnosisCol weak">
        <div class="diagnosisColHead"><b>🔴 Reforço Prioritário (<55%)</b><span>${weak.length}</span></div>
        <div class="diagnosisList">${weak.length?weak.map(x=>renderItem(x,true)).join(''):'<p class="small muted">Nenhum ponto crítico detectado! Continue praticando.</p>'}</div>
      </div>
    `;

    qa('[data-train-diagnosis-subject]').forEach(btn=>btn.onclick=()=>{
      const targetSubj=btn.dataset.trainDiagnosisSubject;
      const subjSel=q('#questionSubject');
      if(subjSel){
        const match=[...subjSel.options].find(opt=>topicKey(opt.value)===topicKey(targetSubj));
        if(match){
          subjSel.value=match.value;
          if(q('#questionBattleMode'))q('#questionBattleMode').value='progressive';
          populateTopicFilter();
          updateQuestionPool();
          startFilteredBattle();
          return;
        }
      }
      switchExamHubTab('generator');
      if(q('#genBankSubject'))q('#genBankSubject').value=targetSubj;
      q('#examBankHub')?.scrollIntoView({behavior:'smooth',block:'center'});
      toast(`Gere um caderno de questões de ${targetSubj} abaixo para iniciar o treino!`);
    });
  }

  function startSubjectTargetedFix(subjectName,preferErrors=true){
    sanitizeAllQuestionsAndErrorsSubjects();
    const cleanSubj=canonicalSubjectName(subjectName);
    const subjKey=topicKey(cleanSubj);
    const allQ=ALL_QUESTIONS||[];
    const eligible=item=>isQuestionDisciplineEligible(item,cleanSubj)&&!['sem_gabarito','anulada'].includes(answerKeyStatus(item));
    const subjPool=allQ.filter(eligible);
    const subjStmtSet=new Set(subjPool.map(item=>topicKey(item.statement||'')));
    const errEntries=activeCampaignErrors().filter(([,e])=>{
      const realErrSubj=resolveStrictQuestionDiscipline(e?.question||'',e?.topic||'',e?.subject||'',e?.options||[]);
      return topicKey(realErrSubj)===subjKey;
    });
    let chosenPool=[];
    if(preferErrors&&errEntries.length){
      const errMatched=subjPool.filter(item=>questionMatchesErrorPool(item,errEntries));
      const originalsFromErrors=errEntries
        .filter(([,e])=>e?.question&&Array.isArray(e.options)&&!subjStmtSet.has(topicKey(e.question)))
        .map(([key,e])=>({...e,subject:cleanSubj,topic:e.topic||'Correção de Erro',statement:e.question,
          options:[...e.options],correct_index:e.correct_index,explanation:e.explanation||'',
          difficulty:e.difficulty||'medio',origin:e.origin||'autoral',_alreadyPreparedConsistent:true,_errorNotebookKey:key}))
        .filter(eligible);
      chosenPool=[...errMatched,...originalsFromErrors,...subjPool];
    }else{
      chosenPool=subjPool;
    }
    // Filtro final estrito: garante que 100% das questões da sessão pertencem exclusivamente à disciplina solicitada
    chosenPool=chosenPool.filter(eligible);
    if(chosenPool.length){
      const seen=new Set();
      const seenStmt=new Set();
      const uniquePool=chosenPool.filter(item=>{
        const fp=questionFingerprint(item);
        const stKey=topicKey(item.statement||'');
        if(seen.has(fp)||(stKey&&seenStmt.has(stKey)))return false;
        seen.add(fp);
        if(stKey)seenStmt.add(stKey);
        return true;
      });
      const count=Math.min(8,uniquePool.length);
      const selected=typeof progressiveQuestions==='function'?progressiveQuestions(uniquePool,count):uniquePool.slice(0,count);
      activeQuestions={
        mode:'battle',
        subject:cleanSubj,
        questions:selected.map(prepareQuestion),
        current:0,
        correct:0,
        streak:0,
        level:1,
        answered:false
      };
      if(q('#questionDialogTitle'))q('#questionDialogTitle').textContent=`🎯 Correção de Gargalo · ${cleanSubj}`;
      q('#questionDialog')?.showModal();
      showQuestion();
      return;
    }
    if(errEntries.length&&typeof window.openTheoryForSubjectAndTopic==='function'){
      window.openTheoryForSubjectAndTopic(cleanSubj,errEntries[0][1]?.topic||'');
      toast('Não há questão original completa com gabarito válido para este erro. Revise a teoria ou importe o item original.');
      return;
    }
    const subjSel=q('#questionSubject');
    if(subjSel){
      const match=[...subjSel.options].find(opt=>topicKey(opt.value)===subjKey);
      if(match){
        subjSel.value=match.value;
        populateTopicFilter();
        updateQuestionPool();
        q('.questionTrainer')?.scrollIntoView({behavior:'smooth',block:'center'});
        toast(`Filtro ajustado para ${cleanSubj}. Inicie a bateria para corrigir este ponto!`);
        return;
      }
    }
    switchExamHubTab('generator');
    if(q('#genBankSubject'))q('#genBankSubject').value=cleanSubj;
    q('#examBankHub')?.scrollIntoView({behavior:'smooth',block:'center'});
    toast(`Gere questões comentadas de ${cleanSubj} para treinar esta disciplina!`);
  }
  window.startSubjectTargetedFix=startSubjectTargetedFix;

  function renderPerformanceChart(){
    sanitizeAllQuestionsAndErrorsSubjects();
    const root=q('#performanceChart');if(!root)return;
    const scores=(state?.scores||[]).filter(item=>!item.campaignId||item.campaignId===state.activeCampaignId),groups={};
    for(const item of scores){
      const rawName=item.subject||missionPool().find(m=>m.id===item.id)?.subject||'Conteúdo geral';
      const name=canonicalSubjectName(rawName, `${item.topic||''} ${item.name||''}`);
      if(isInvalidTrailSubject(name))continue;
      groups[name]??={total:0,correct:0,misses:0};
      groups[name].total+=Number(item.total||0);
      groups[name].correct+=Number(item.correct||0);
    }
    for(const [,err] of activeCampaignErrors()){
      const name=resolveStrictQuestionDiscipline(err?.question||'',err?.topic||'',err?.subject||'',err?.options||[]);
      if(isInvalidTrailSubject(name))continue;
      groups[name]??={total:0,correct:0,misses:0};
      groups[name].misses+=Number(err?.misses||1);
    }
    const editalOrder=(typeof orderedMissions==='function'?orderedMissions():[]).map(m=>subjectKey(canonicalSubjectName(m?.subject||''))).filter(Boolean);
    const rows=Object.entries(groups).filter(([,data])=>data.total>0||data.misses>0).sort((a,b)=>{
      const ia=editalOrder.indexOf(subjectKey(a[0])),ib=editalOrder.indexOf(subjectKey(b[0]));
      if(ia!==-1&&ib!==-1&&ia!==ib)return ia-ib;
      const ra=a[1].total?a[1].correct/a[1].total:0;
      const rb=b[1].total?b[1].correct/b[1].total:0;
      return ra-rb||(b[1].misses-a[1].misses);
    });
    root.className='performanceChart';
    root.innerHTML=rows.length?rows.map(([name,data])=>{
      const rate=data.total?Math.round(data.correct/data.total*100):0;
      const tone=rate<60?'low':rate<72?'mid':'high';
      const statusLabel=rate>=72?'✓ Acima do corte (≥72%)':rate>=60?'⚡ Na disputa (meta: 72%)':'🔴 Abaixo do corte (<60%)';
      return `<div class="performanceBar ${tone}" title="${escText(name)}: ${data.correct}/${data.total}">
        <div class="perfBarHead">
          <span class="perfSubjectName">${escText(name)}</span>
          <div class="perfBarRight">
            <span class="perfMetaCount">${data.total?`${data.correct}/${data.total} acertos`:""}${data.misses?`${data.total?" · ":""}${data.misses} erro(s)`:""}</span>
            <b>${rate}%</b>
          </div>
        </div>
        <div class="performanceTrack">
          <i style="width:${rate}%"></i>
          <s class="perfCutoffTick" style="left:72%" title="Meta de Corte: 72%"></s>
        </div>
        <div class="perfBarFoot">
          <small class="muted">${statusLabel}</small>
          <div style="display:flex;gap:6px;align-items:center">
            ${data.misses?`<button type="button" class="ghost small" data-perf-clear-errors="${escText(name)}" style="width:auto;padding:4px 8px;font-size:.72rem;opacity:.85" title="Zerar erros acumulados de ${escText(name)}">🗑️ Limpar erros</button>`:''}
            <button type="button" class="ghost small perfTrainBtn" data-perf-train-subject="${escText(name)}">${rate<72||data.misses?'🔧 Corrigir →':'Treinar →'}</button>
          </div>
        </div>
      </div>`;
    }).join(''):'<div class="empty">Resolva questões para visualizar sua precisão por disciplina e distância para o corte de 72%.</div>';
    const boardRows=questionBoardPerformanceRows(q('#questionSubject')?.value||'all');
    root.insertAdjacentHTML('beforeend',`<section class="card" aria-label="Desempenho por banca"><h4>Desempenho por banca e disciplina</h4><p class="small muted">Respostas registradas a partir desta revisão. Questões autorais no estilo da banca ficam separadas das questões de documentos. Sugestões de gabarito da IA pendentes não pontuam.</p>${boardRows.length?boardRows.slice(0,30).map(row=>`<div class="performanceBar"><div class="perfBarHead"><span>${escText(row.board)} · ${escText(row.subject)} · ${row.origin==='autoral'?'Estilo autoral':'Documento'}</span><b>${row.correct}/${row.total} (${row.rate}%)</b></div><p class="small muted">Primeira tentativa: ${row.firstCorrect}/${row.firstTotal}${row.firstRate!==null?` (${row.firstRate}%)`:''} · Repetições: ${row.repeatTotal}${row.averageSeconds!==null?` · Tempo médio: ${row.averageSeconds}s (${row.timedTotal} cronometradas)`:''}${row.lowSample?' · Amostra pequena (menos de 30 questões distintas)':''}</p></div>`).join(''):'<p class="small muted">Responda questões para iniciar esta estatística. O histórico antigo não permite reconstruir a banca com segurança.</p>'}</section>`);
    root.querySelectorAll('[data-perf-train-subject]').forEach(btn=>{
      btn.onclick=()=>startSubjectTargetedFix(btn.dataset.perfTrainSubject,true);
    });
    root.querySelectorAll('[data-perf-clear-errors]').forEach(btn=>{
      btn.onclick=()=>{
        const targetSubj=btn.dataset.perfClearErrors;
        const targetKey=topicKey(canonicalSubjectName(targetSubj));
        let removed=0;
        for(const [k,e] of Object.entries(state?.errors||{})){
          const eSubj=resolveStrictQuestionDiscipline(e?.question||'',e?.topic||'',e?.subject||'',e?.options||[]);
          if(topicKey(eSubj)===targetKey||topicKey(canonicalSubjectName(e?.subject||''))===targetKey){
            delete state.errors[k];
            removed++;
          }
        }
        if(typeof save==='function')save();
        renderPerformanceChart();
        if(typeof renderErrorNotebook==='function')renderErrorNotebook();
        updateQuestionPool();
        toast(`✓ ${removed} registro(s) de erro de ${targetSubj} limpo(s)!`);
      };
    });
    renderTacticalDiagnosis();
    renderCutoffThermometer();
  }

